    private static string ExpectedSpectatorPendingTaskQueueActiveTaskId(MatchState authoritativeState)
    {
        var queue = authoritativeState.PendingTaskQueue;
        var activeTask = queue.Tasks.FirstOrDefault(task =>
            string.Equals(task.TaskId, queue.ActiveTaskId, StringComparison.Ordinal));
        return activeTask is null
            ? queue.ActiveTaskId ?? string.Empty
            : VisibleCleanupTaskIdForRecovery(authoritativeState, activeTask);
    }

    private static string VisibleCleanupTaskIdForRecovery(MatchState authoritativeState, CleanupTaskState task)
    {
        if (!ShouldHideCleanupTaskObjectIdForRecovery(authoritativeState, task))
        {
            return task.TaskId;
        }

        var ordinal = HiddenStandbyOrdinalForRecovery(
            authoritativeState,
            task.ObjectId!,
            task.BattlefieldObjectId);
        return $"cleanup:illegal-standby:{task.BattlefieldObjectId}:hidden-standby-{ordinal}";
    }

    private static bool ShouldHideCleanupTaskObjectIdForRecovery(MatchState authoritativeState, CleanupTaskState task)
    {
        return string.Equals(task.Kind, "REMOVE_ILLEGAL_STANDBY", StringComparison.Ordinal)
            && !string.IsNullOrWhiteSpace(task.ObjectId)
            && authoritativeState.CardObjects.TryGetValue(task.ObjectId, out var cardObject)
            && cardObject.IsFaceDown
            && cardObject.Tags.Contains(CardObjectTags.Standby, StringComparer.Ordinal);
    }

    private static int HiddenStandbyOrdinalForRecovery(
        MatchState authoritativeState,
        string objectId,
        string? battlefieldObjectId)
    {
        if (string.IsNullOrWhiteSpace(battlefieldObjectId)
            || !authoritativeState.BattlefieldStates.TryGetValue(battlefieldObjectId, out var battlefield))
        {
            return 1;
        }

        var hiddenIds = battlefield.StandbyObjectIds
            .Where(candidate => IsHiddenBattlefieldStandbyForSpectator(authoritativeState, candidate))
            .OrderBy(candidate => candidate, StringComparer.Ordinal)
            .ToArray();
        var index = Array.IndexOf(hiddenIds, objectId);
        return index < 0 ? 1 : index + 1;
    }

    private static IReadOnlyList<string> ExpectedStateBasedTaskKinds(IReadOnlyList<CleanupTaskState> tasks)
    {
        return ExpectedStateBasedTaskKinds(tasks.Select(task => task.Kind));
    }

    private static IReadOnlyList<string> ExpectedStateBasedTaskKinds(IEnumerable<string> taskKinds)
    {
        return taskKinds
            .Where(IsSnapshotStateBasedCleanupTaskForRecovery)
            .Distinct(StringComparer.Ordinal)
            .OrderBy(kind => kind, StringComparer.Ordinal)
            .ToArray();
    }

    private static bool IsSnapshotStateBasedCleanupTaskForRecovery(string kind)
    {
        return string.Equals(kind, "DESTROY_LETHAL_UNIT", StringComparison.Ordinal)
            || string.Equals(kind, "DESTROY_ZERO_POWER_UNIT", StringComparison.Ordinal)
            || string.Equals(kind, "REMOVE_ILLEGAL_STANDBY", StringComparison.Ordinal)
            || string.Equals(kind, "RECALL_UNATTACHED_EQUIPMENT", StringComparison.Ordinal);
    }

    private static void ValidateSpectatorPendingPaymentPayload(
        IReadOnlyDictionary<string, object?> timing,
        MatchState authoritativeState,
        List<string> errors)
    {
        var authoritativePayment = authoritativeState.PendingPayment;
        if (!timing.TryGetValue("pendingPayment", out var paymentPayload))
        {
            errors.Add("spectator replay frame timing pending payment is required");
            AddMissingSpectatorPendingPaymentDiagnostics(authoritativeState, authoritativePayment, errors);
            return;
        }

        if (authoritativePayment is null)
        {
            if (!IsNullSnapshotPayloadValue(paymentPayload))
            {
                errors.Add("spectator replay frame timing pending payment must be empty when authoritative state has no pending payment");
            }

            return;
        }

        if (IsNullSnapshotPayloadValue(paymentPayload))
        {
            errors.Add("spectator replay frame timing pending payment is required");
            AddMissingSpectatorPendingPaymentDiagnostics(authoritativeState, authoritativePayment, errors);
            return;
        }

        if (!IsSnapshotPlayerPayloadObject(paymentPayload))
        {
            errors.Add("spectator replay frame timing pending payment payload is required");
            return;
        }

        ValidateSnapshotPayloadObjectPropertyNames(
            paymentPayload,
            "spectator replay frame timing pending payment",
            errors);
        ValidateSpectatorPendingPaymentPayloadValues(paymentPayload, errors);

        ValidateSpectatorPendingPaymentRequiredStringAuthoritativeValue(
            paymentPayload,
            "paymentId",
            "id",
            authoritativePayment.PaymentId,
            errors);
        ValidateSpectatorPendingPaymentRequiredStringAuthoritativeValue(
            paymentPayload,
            "paymentWindow",
            "window",
            authoritativePayment.PaymentWindow,
            errors);
        ValidateSpectatorPendingPaymentRequiredStringAuthoritativeValue(
            paymentPayload,
            "playerId",
            "player",
            authoritativePayment.PlayerId,
            errors);

        if (!TryReadObjectValue(paymentPayload, "cost", out var costPayload)
            || IsNullSnapshotPayloadValue(costPayload))
        {
            errors.Add("spectator replay frame timing pending payment cost is required");
        }
        else if (!IsSnapshotPlayerPayloadObject(costPayload))
        {
            errors.Add("spectator replay frame timing pending payment cost payload is required");
        }
        else
        {
            ValidateSnapshotPayloadObjectPropertyNames(
                costPayload,
                "spectator replay frame timing pending payment cost",
                errors);
            ValidateSpectatorPendingPaymentPowerTraitPayloadPropertyNames(costPayload, errors);

            ValidateSpectatorPendingPaymentRequiredIntAuthoritativeValue(
                costPayload,
                "mana",
                "mana cost",
                authoritativePayment.ManaCost,
                errors);
            ValidateSpectatorPendingPaymentRequiredIntAuthoritativeValue(
                costPayload,
                "power",
                "power cost",
                authoritativePayment.PowerCost,
                errors);
            ValidateSpectatorPendingPaymentRequiredIntDictionaryAuthoritativeValue(
                costPayload,
                "powerByTrait",
                "power cost traits",
                authoritativePayment.PowerCostByTrait,
                errors);
        }

        ValidateSpectatorPendingPaymentRequiredStringListAuthoritativeValue(
            paymentPayload,
            "paymentChoices",
            "choices",
            authoritativePayment.LegalPaymentChoiceIds,
            errors);

        ValidateSpectatorPendingPaymentRequiredStringListAuthoritativeValue(
            paymentPayload,
            "paymentResourceActions",
            "resource actions",
            ExpectedSpectatorPendingPaymentResourceActionIds(authoritativeState, authoritativePayment),
            errors);
    }

    private static void AddMissingSpectatorPendingPaymentDiagnostics(
        MatchState authoritativeState,
        PendingPaymentState? authoritativePayment,
        List<string> errors)
    {
        if (authoritativePayment is null)
        {
            return;
        }

        if (authoritativePayment.ManaCost > 0)
        {
            errors.Add(
                $"spectator replay frame timing pending payment mana cost 0 does not match authoritative state pending payment mana cost {authoritativePayment.ManaCost}");
        }

        if (authoritativePayment.PowerCost > 0)
        {
            errors.Add(
                $"spectator replay frame timing pending payment power cost 0 does not match authoritative state pending payment power cost {authoritativePayment.PowerCost}");
        }

        if (authoritativePayment.PowerCostByTrait.Count > 0)
        {
            errors.Add(
                $"spectator replay frame timing pending payment power cost trait count 0 does not match authoritative state pending payment power cost trait count {authoritativePayment.PowerCostByTrait.Count}");
        }

        if (authoritativePayment.LegalPaymentChoiceIds.Count > 0)
        {
            errors.Add(
                $"spectator replay frame timing pending payment choice count 0 does not match authoritative state pending payment choice count {authoritativePayment.LegalPaymentChoiceIds.Count}");
        }

        var expectedResourceActionCount =
            ExpectedSpectatorPendingPaymentResourceActionIds(authoritativeState, authoritativePayment).Count;
        if (expectedResourceActionCount > 0)
        {
            errors.Add(
                $"spectator replay frame timing pending payment resource action count 0 does not match authoritative state pending payment resource action count {expectedResourceActionCount}");
        }
    }

    private static void ValidateSpectatorPendingPaymentPayloadValues(
        object? paymentPayload,
        List<string> errors)
    {
        const string payloadLabel = "spectator replay frame timing pending payment";
        ValidateSnapshotPayloadRequiredStringValue(
            paymentPayload,
            "paymentId",
            payloadLabel,
            "payment id",
            errors);
        ValidateSnapshotPayloadRequiredStringValue(
            paymentPayload,
            "paymentWindow",
            payloadLabel,
            "payment window",
            errors);
        ValidateSnapshotPayloadRequiredStringValue(
            paymentPayload,
            "playerId",
            payloadLabel,
            "player id",
            errors);
        ValidateSpectatorRequiredStringListPayloadShape(
            paymentPayload,
            payloadLabel,
            "paymentChoices",
            "payment choice",
            errors);
        ValidateSnapshotPayloadStringListValues(
            paymentPayload,
            "paymentChoices",
            payloadLabel,
            "payment choice",
            errors);
        ValidateSpectatorRequiredStringListPayloadShape(
            paymentPayload,
            payloadLabel,
            "paymentResourceActions",
            "payment resource action",
            errors);
        ValidateSnapshotPayloadStringListValues(
            paymentPayload,
            "paymentResourceActions",
            payloadLabel,
            "payment resource action",
            errors);

        if (!TryReadObjectValue(paymentPayload, "cost", out var costPayload)
            || !IsSnapshotPlayerPayloadObject(costPayload))
        {
            return;
        }

        ValidateSnapshotPayloadRequiredNonNegativeIntValue(
            costPayload,
            "mana",
            $"{payloadLabel} cost",
            "mana",
            errors);
        ValidateSnapshotPayloadRequiredNonNegativeIntValue(
            costPayload,
            "power",
            $"{payloadLabel} cost",
            "power",
            errors);
        ValidateSpectatorRequiredIntMapPayloadShape(
            costPayload,
            $"{payloadLabel} cost",
            "powerByTrait",
            "power cost trait",
            errors);
        ValidateSnapshotPayloadRequiredPositiveIntMapValues(
            costPayload,
            "powerByTrait",
            $"{payloadLabel} cost",
            "power cost trait",
            errors);
    }

    private static void ValidateSpectatorPendingPaymentRequiredStringAuthoritativeValue(
        object? paymentPayload,
        string key,
        string fieldLabel,
        string expected,
        List<string> errors)
    {
        var readable = TryReadObjectString(paymentPayload, key, out var actual);
        if (readable
            && string.Equals(actual, expected, StringComparison.Ordinal))
        {
            return;
        }

        AddSpectatorPendingPaymentAuthoritativeMismatch(
            fieldLabel,
            "does",
            expected,
            readable ? actual : FormatUnreadableObjectValue(paymentPayload, key),
            errors);
    }

    private static void ValidateSpectatorPendingPaymentRequiredIntAuthoritativeValue(
        object? costPayload,
        string key,
        string fieldLabel,
        int expected,
        List<string> errors)
    {
        var readable = TryReadObjectInt(costPayload, key, out var actual);
        if (readable && actual == expected)
        {
            return;
        }

        AddSpectatorPendingPaymentAuthoritativeMismatch(
            fieldLabel,
            "does",
            expected,
            readable ? actual : FormatUnreadableObjectValue(costPayload, key),
            errors);
    }

    private static void ValidateSpectatorPendingPaymentRequiredIntDictionaryAuthoritativeValue(
        object? costPayload,
        string key,
        string fieldLabel,
        IReadOnlyDictionary<string, int> expected,
        List<string> errors)
    {
        var readable = TryReadObjectIntDictionary(costPayload, key, out var actual);
        if (readable && IntDictionariesEqual(actual, expected))
        {
            return;
        }

        AddSpectatorPendingPaymentAuthoritativeMismatch(
            fieldLabel,
            "do",
            expected,
            readable ? actual : FormatUnreadableObjectValue(costPayload, key),
            errors);
    }

    private static void ValidateSpectatorPendingPaymentRequiredStringListAuthoritativeValue(
        object? paymentPayload,
        string key,
        string fieldLabel,
        IReadOnlyList<string> expected,
        List<string> errors)
    {
        var readable = TryReadObjectStringList(paymentPayload, key, out var actual);
        if (readable && StringListsEqual(actual, expected))
        {
            return;
        }

        AddSpectatorPendingPaymentAuthoritativeMismatch(
            fieldLabel,
            "do",
            expected,
            readable ? actual : FormatUnreadableObjectValue(paymentPayload, key),
            errors);
    }

    private static void AddSpectatorPendingPaymentAuthoritativeMismatch(
        string fieldLabel,
        string matchVerb,
        object? expected,
        object? actual,
        List<string> errors)
    {
        errors.Add(
            $"spectator replay frame timing pending payment {fieldLabel} {matchVerb} not match authoritative state pending payment {fieldLabel}; {FormatExpectedActualForRecovery(expected, actual)}");
    }

    private static IReadOnlyList<string> ExpectedSpectatorPendingPaymentResourceActionIds(
        MatchState authoritativeState,
        PendingPaymentState payment)
    {
        return payment.PaymentResourceActionIds
            .Concat(payment.LegalPaymentChoiceIds.Where(choiceId =>
                choiceId.StartsWith("RECYCLE_RUNE:", StringComparison.Ordinal)))
            .Concat(ExpectedTemporaryPaymentResourceActionIdsForRecovery(authoritativeState, payment))
            .Concat(ExpectedBlueSentinelDelayedResourceActionIdsForRecovery(authoritativeState, payment))
            .Distinct(StringComparer.Ordinal)
            .ToArray();
    }

    private static IReadOnlyList<string> ExpectedTemporaryPaymentResourceActionIdsForRecovery(
        MatchState authoritativeState,
        PendingPaymentState payment)
    {
        if (payment.PowerCost <= 0 && payment.PowerCostByTrait.Count == 0)
        {
            return [];
        }

        var runePool = authoritativeState.RunePools.TryGetValue(payment.PlayerId, out var currentPool)
            ? currentPool
            : RunePool.Empty;
        if (PaymentCostRules.CanPayPowerCost(runePool, payment.PowerCost, payment.PowerCostByTrait))
        {
            return [];
        }

        return authoritativeState.TemporaryPaymentResources
            .Where(resource => string.Equals(resource.OwnerPlayerId, payment.PlayerId, StringComparison.Ordinal)
                && TemporaryPaymentResourceTotalRemainingPowerForRecovery(resource) > 0
                && resource.AllowedPaymentKinds.Contains(PaymentCostRules.RuneCostPaymentKind, StringComparer.Ordinal)
                && TemporaryPaymentResourceCanHelpPowerCostForRecovery(
                    runePool,
                    resource,
                    payment.PowerCost,
                    payment.PowerCostByTrait))
            .Select(resource => PaymentCostRules.TemporaryPaymentResourceActionId(resource.ResourceId))
            .ToArray();
    }

    private static IReadOnlyList<string> ExpectedBlueSentinelDelayedResourceActionIdsForRecovery(
        MatchState authoritativeState,
        PendingPaymentState payment)
    {
        if (payment.PowerCost <= 0 && payment.PowerCostByTrait.Count == 0)
        {
            return [];
        }

        var runePool = authoritativeState.RunePools.TryGetValue(payment.PlayerId, out var currentPool)
            ? currentPool
            : RunePool.Empty;
        if (PaymentCostRules.CanPayPowerCost(runePool, payment.PowerCost, payment.PowerCostByTrait))
        {
            return [];
        }

        return authoritativeState.TriggerQueue
            .Where(trigger => BlueSentinelDelayedTriggerCanPayForRecovery(authoritativeState, payment, trigger))
            .Select(trigger => $"{P4ActivatedAbilityCatalog.BlueSentinelDelayedResourceActionPrefix}{trigger.TriggerId}")
            .ToArray();
    }

    private static bool BlueSentinelDelayedTriggerCanPayForRecovery(
        MatchState authoritativeState,
        PendingPaymentState payment,
        TriggerQueueItemState trigger)
    {
        if (!TryReadBlueSentinelDelayedTriggerContextForRecovery(
                trigger.TriggerId,
                out var capturedTurnNumber,
                out var sourceObjectId,
                out var battlefieldObjectId)
            || !string.Equals(trigger.ControllerId, payment.PlayerId, StringComparison.Ordinal)
            || !string.Equals(trigger.SourceObjectId, sourceObjectId, StringComparison.Ordinal)
            || !string.Equals(trigger.EffectKind, P4ActivatedAbilityCatalog.BlueSentinelResourceAbilityEffectKind, StringComparison.Ordinal)
            || !string.Equals(trigger.TriggeredByEventKind, "BATTLEFIELD_HELD", StringComparison.Ordinal)
            || authoritativeState.TurnNumber != capturedTurnNumber + 1
            || !string.Equals(authoritativeState.Phase, MatchPhases.Main, StringComparison.Ordinal)
            || !string.Equals(authoritativeState.TimingState, TimingStates.NeutralOpen, StringComparison.Ordinal)
            || !string.Equals(authoritativeState.ActivePlayerId, payment.PlayerId, StringComparison.Ordinal)
            || !BlueSentinelDelayedSourceStillHoldsBattlefieldForRecovery(
                authoritativeState,
                payment.PlayerId,
                sourceObjectId,
                battlefieldObjectId))
        {
            return false;
        }

        var runePool = authoritativeState.RunePools.TryGetValue(payment.PlayerId, out var currentPool)
            ? currentPool
            : RunePool.Empty;
        return TemporaryPaymentResourceCanHelpPowerCostForRecovery(
            runePool,
            new TemporaryPaymentResourceState(
                $"BLUE_SENTINEL:QUOTE:{trigger.TriggerId}",
                payment.PlayerId,
                sourceObjectId,
                P4ActivatedAbilityCatalog.BlueSentinelResourceAbilityId,
                payment.PaymentWindow,
                generatedPower: P4ActivatedAbilityCatalog.BlueSentinelGeneratedPower,
                remainingPower: P4ActivatedAbilityCatalog.BlueSentinelGeneratedPower,
                allowedPaymentKinds: [PaymentCostRules.RuneCostPaymentKind],
                createdTick: authoritativeState.Tick),
            payment.PowerCost,
            payment.PowerCostByTrait);
    }

    private static bool TryReadBlueSentinelDelayedTriggerContextForRecovery(
        string triggerId,
        out int capturedTurnNumber,
        out string sourceObjectId,
        out string battlefieldObjectId)
    {
        capturedTurnNumber = 0;
        sourceObjectId = string.Empty;
        battlefieldObjectId = string.Empty;
        var parts = triggerId.Split("::", StringSplitOptions.None);
        if (parts.Length != 4
            || !string.Equals(parts[0], BlueSentinelDelayedTriggerIdPrefixForRecovery, StringComparison.Ordinal)
            || !int.TryParse(
                parts[1],
                System.Globalization.NumberStyles.Integer,
                System.Globalization.CultureInfo.InvariantCulture,
                out capturedTurnNumber)
            || string.IsNullOrWhiteSpace(parts[2])
            || string.IsNullOrWhiteSpace(parts[3]))
        {
            return false;
        }

        sourceObjectId = parts[2];
        battlefieldObjectId = parts[3];
        return capturedTurnNumber > 0;
    }

    private static bool BlueSentinelDelayedSourceStillHoldsBattlefieldForRecovery(
        MatchState authoritativeState,
        string playerId,
        string sourceObjectId,
        string battlefieldObjectId)
    {
        return authoritativeState.CardObjects.TryGetValue(sourceObjectId, out var sourceState)
            && string.Equals(sourceState.CardNo, P4ActivatedAbilityCatalog.BlueSentinelCardNo, StringComparison.Ordinal)
            && sourceState.Tags.Contains(CardObjectTags.UnitCard, StringComparer.Ordinal)
            && !sourceState.IsFaceDown
            && !sourceState.Tags.Contains(CardObjectTags.Standby, StringComparer.Ordinal)
            && SourceObjectControlledByPlayerOrLegacyOwnedForRecovery(sourceState, playerId)
            && authoritativeState.ObjectLocations.TryGetValue(sourceObjectId, out var sourceLocation)
            && string.Equals(sourceLocation.Zone, "BATTLEFIELD", StringComparison.Ordinal)
            && string.Equals(sourceLocation.BattlefieldObjectId, battlefieldObjectId, StringComparison.Ordinal)
            && authoritativeState.PlayerZones.TryGetValue(playerId, out var zones)
            && zones.Battlefields.Contains(sourceObjectId, StringComparer.Ordinal)
            && (!authoritativeState.CardObjects.TryGetValue(battlefieldObjectId, out var battlefieldState)
                || SourceObjectControlledByPlayerOrLegacyOwnedForRecovery(battlefieldState, playerId));
    }

    private static int TemporaryPaymentResourceTotalRemainingPowerForRecovery(TemporaryPaymentResourceState resource)
    {
        return resource.RemainingPower + resource.RemainingPowerByTrait.Values.Sum();
    }

    private static bool TemporaryPaymentResourceCanHelpPowerCostForRecovery(
        RunePool runePool,
        TemporaryPaymentResourceState resource,
        int genericPowerCost,
        IReadOnlyDictionary<string, int> powerCostByTrait)
    {
        if (PaymentCostRules.CanPayPowerCost(runePool, genericPowerCost, powerCostByTrait)
            || TemporaryPaymentResourceTotalRemainingPowerForRecovery(resource) <= 0)
        {
            return false;
        }

        var powerByTrait = runePool.PowerByTrait.ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        foreach (var entry in resource.RemainingPowerByTrait)
        {
            powerByTrait[entry.Key] = powerByTrait.TryGetValue(entry.Key, out var existing)
                ? existing + entry.Value
                : entry.Value;
        }

        return PaymentCostRules.CanPayPowerCost(
            new RunePool(runePool.Mana, runePool.Power + resource.RemainingPower, powerByTrait),
            genericPowerCost,
            powerCostByTrait);
    }

    private static void ValidateSpectatorContinuousEffectPayloads(
        IReadOnlyDictionary<string, object?> timing,
        MatchState authoritativeState,
        List<string> errors)
    {
        if (!timing.TryGetValue("continuousEffects", out var continuousEffectsPayload)
            || IsNullSnapshotPayloadValue(continuousEffectsPayload))
        {
            errors.Add("spectator replay frame timing continuous effects are required");
            var authoritativeEffectCount = authoritativeState.ContinuousEffects.Count;
            if (authoritativeEffectCount > 0)
            {
                AddSpectatorContinuousEffectCountMismatch(
                    spectatorCount: 0,
                    authoritativeCount: authoritativeEffectCount,
                    errors);
            }

            ReportMissingSpectatorContinuousEffectAuthoritativeKeySet(
                authoritativeState.ContinuousEffects,
                errors);
            return;
        }

        if (!TryReadObjectListValue(continuousEffectsPayload, out var spectatorEffects))
        {
            errors.Add("spectator replay frame timing continuous effects payload is required");
            var authoritativeEffectCount = authoritativeState.ContinuousEffects.Count;
            if (authoritativeEffectCount > 0)
            {
                AddSpectatorContinuousEffectCountMismatch(
                    spectatorCount: 0,
                    authoritativeCount: authoritativeEffectCount,
                    errors);
            }

            ReportMissingSpectatorContinuousEffectAuthoritativeKeySet(
                authoritativeState.ContinuousEffects,
                errors);
            return;
        }

        var authoritativeEffects = authoritativeState.ContinuousEffects;
        var validateAuthoritativeParity = spectatorEffects.Count == authoritativeEffects.Count;
        if (!validateAuthoritativeParity)
        {
            AddSpectatorContinuousEffectCountMismatch(
                spectatorEffects.Count,
                authoritativeEffects.Count,
                errors);
        }

        var seenEffectIds = new HashSet<string>(StringComparer.Ordinal);
        var seenSequences = new HashSet<int>();
        var validSequences = new List<int>();
        var knownObjectIds = BuildAuthoritativeStateKnownObjectIds(authoritativeState);
        foreach (var spectatorEffect in spectatorEffects)
        {
            if (!IsSnapshotPlayerPayloadObject(spectatorEffect))
            {
                errors.Add("spectator replay frame timing continuous effect payload is required");
                continue;
            }

            ValidateSnapshotPayloadObjectPropertyNames(
                spectatorEffect,
                "spectator replay frame timing continuous effect item",
                errors);
            var effectValues = ValidateSpectatorContinuousEffectPayloadValues(
                spectatorEffect,
                knownObjectIds,
                errors);
            if (effectValues.EffectId is not null && !seenEffectIds.Add(effectValues.EffectId))
            {
                errors.Add(
                    $"spectator replay frame timing continuous effect item effect id {effectValues.EffectId} is duplicated");
            }

            ValidateContinuousEffectSequenceValue(
                "spectator replay frame timing continuous effect item",
                effectValues.Sequence,
                seenSequences,
                validSequences,
                errors);
        }

        ValidateContinuousEffectSequenceContinuity(
            "spectator replay frame timing continuous effect item",
            validSequences,
            errors);

        var authoritativeEffectsById = BuildAuthoritativeContinuousEffectsById(authoritativeEffects);
        ValidateSpectatorContinuousEffectAuthoritativeKeySet(
            spectatorEffects,
            authoritativeEffectsById,
            errors);
        ValidateSpectatorContinuousEffectKeyedAuthoritativeValues(
            spectatorEffects,
            authoritativeEffectsById,
            errors);

        if (!validateAuthoritativeParity)
        {
            return;
        }

        var effectIdsMatch = true;
        var scopesMatch = true;
        var layersMatch = true;
        var durationsMatch = true;
        var targetObjectIdsMatch = true;
        var sourceObjectIdsMatch = true;
        var powerDeltasMatch = true;
        var basePowersMatch = true;
        var effectivePowersMatch = true;
        var sequencesMatch = true;
        var effectKindsMatch = true;
        var sourceCardNumbersMatch = true;
        var sourcePathsMatch = true;
        var layerEngineStatusesMatch = true;
        var requestedPowerDeltasMatch = true;
        var appliedPowerDeltasMatch = true;
        var minimumPowersMatch = true;
        var resultingPowersMatch = true;
        var appliedOrdersMatch = true;
        var sourceOrdersMatch = true;
        var conditionsMatch = true;
        var lifecyclesMatch = true;
        var participantObjectIdsMatch = true;
        var sourceDependencyObjectIdsMatch = true;
        var targetDependencyObjectIdsMatch = true;
        var participantDependencyObjectIdsMatch = true;
        var deferredLayerEngineResidualsMatch = true;

        for (var index = 0; index < authoritativeEffects.Count; index++)
        {
            var spectatorEffect = spectatorEffects[index];
            if (!IsSnapshotPlayerPayloadObject(spectatorEffect))
            {
                continue;
            }

            var authoritativeEffect = authoritativeEffects[index];
            if (!TryReadObjectString(spectatorEffect, "effectId", out var effectId)
                || !string.Equals(effectId, authoritativeEffect.EffectId, StringComparison.Ordinal))
            {
                effectIdsMatch = false;
            }

            if (!TryReadObjectString(spectatorEffect, "scope", out var scope)
                || !string.Equals(scope, authoritativeEffect.Scope, StringComparison.Ordinal))
            {
                scopesMatch = false;
            }

            if (!TryReadObjectString(spectatorEffect, "layer", out var layer)
                || !string.Equals(layer, authoritativeEffect.Layer, StringComparison.Ordinal))
            {
                layersMatch = false;
            }

            if (!TryReadObjectString(spectatorEffect, "duration", out var duration)
                || !string.Equals(duration, authoritativeEffect.Duration, StringComparison.Ordinal))
            {
                durationsMatch = false;
            }

            if (!TryReadObjectValue(spectatorEffect, "targetObjectId", out var targetObjectIdPayload)
                || !TryReadOptionalStringValue(targetObjectIdPayload, out var targetObjectId)
                || !string.Equals(
                    targetObjectId,
                    authoritativeEffect.TargetObjectId ?? string.Empty,
                    StringComparison.Ordinal))
            {
                targetObjectIdsMatch = false;
            }

            if (!TryReadObjectValue(spectatorEffect, "sourceObjectId", out var sourceObjectIdPayload)
                || !TryReadOptionalStringValue(sourceObjectIdPayload, out var sourceObjectId)
                || !string.Equals(
                    sourceObjectId,
                    authoritativeEffect.SourceObjectId ?? string.Empty,
                    StringComparison.Ordinal))
            {
                sourceObjectIdsMatch = false;
            }

            if (!TryReadObjectInt(spectatorEffect, "powerDelta", out var powerDelta)
                || powerDelta != authoritativeEffect.PowerDelta)
            {
                powerDeltasMatch = false;
            }

            if (!TryReadObjectInt(spectatorEffect, "basePower", out var basePower)
                || basePower != authoritativeEffect.BasePower)
            {
                basePowersMatch = false;
            }

            if (!TryReadObjectInt(spectatorEffect, "effectivePower", out var effectivePower)
                || effectivePower != authoritativeEffect.EffectivePower)
            {
                effectivePowersMatch = false;
            }

            if (!TryReadObjectInt(spectatorEffect, "sequence", out var sequence)
                || sequence != authoritativeEffect.Sequence)
            {
                sequencesMatch = false;
            }

            if (!OptionalStringSnapshotValueMatches(spectatorEffect, "effectKind", authoritativeEffect.EffectKind))
            {
                effectKindsMatch = false;
            }

            if (!OptionalStringSnapshotValueMatches(spectatorEffect, "sourceCardNo", authoritativeEffect.SourceCardNo))
            {
                sourceCardNumbersMatch = false;
            }

            if (!OptionalStringSnapshotValueMatches(spectatorEffect, "sourcePath", authoritativeEffect.SourcePath))
            {
                sourcePathsMatch = false;
            }

            if (!OptionalStringSnapshotValueMatches(
                    spectatorEffect,
                    "layerEngineStatus",
                    authoritativeEffect.IsLayerEngineFoundationOnly ? "FOUNDATION_ONLY" : null))
            {
                layerEngineStatusesMatch = false;
            }

            if (!OptionalIntSnapshotValueMatches(
                    spectatorEffect,
                    "requestedPowerDelta",
                    authoritativeEffect.RequestedPowerDelta))
            {
                requestedPowerDeltasMatch = false;
            }

            if (!OptionalIntSnapshotValueMatches(
                    spectatorEffect,
                    "appliedPowerDelta",
                    authoritativeEffect.AppliedPowerDelta))
            {
                appliedPowerDeltasMatch = false;
            }

            if (!OptionalIntSnapshotValueMatches(spectatorEffect, "minimumPower", authoritativeEffect.MinimumPower))
            {
                minimumPowersMatch = false;
            }

            if (!OptionalIntSnapshotValueMatches(spectatorEffect, "resultingPower", authoritativeEffect.ResultingPower))
            {
                resultingPowersMatch = false;
            }

            if (!OptionalIntSnapshotValueMatches(spectatorEffect, "appliedOrder", authoritativeEffect.AppliedOrder))
            {
                appliedOrdersMatch = false;
            }

            if (!OptionalIntSnapshotValueMatches(spectatorEffect, "sourceOrder", authoritativeEffect.SourceOrder))
            {
                sourceOrdersMatch = false;
            }

            if (!OptionalStringSnapshotValueMatches(spectatorEffect, "condition", authoritativeEffect.Condition))
            {
                conditionsMatch = false;
            }

            if (!OptionalStringSnapshotValueMatches(spectatorEffect, "lifecycle", authoritativeEffect.Lifecycle))
            {
                lifecyclesMatch = false;
            }

            if (!OptionalStringListSnapshotValueMatches(
                    spectatorEffect,
                    "participantObjectIds",
                    authoritativeEffect.ParticipantObjectIds))
            {
                participantObjectIdsMatch = false;
            }

            if (!OptionalStringListSnapshotValueMatches(
                    spectatorEffect,
                    "sourceDependencyObjectIds",
                    authoritativeEffect.SourceDependencyObjectIds))
            {
                sourceDependencyObjectIdsMatch = false;
            }

            if (!OptionalStringListSnapshotValueMatches(
                    spectatorEffect,
                    "targetDependencyObjectIds",
                    authoritativeEffect.TargetDependencyObjectIds))
            {
                targetDependencyObjectIdsMatch = false;
            }

            if (!OptionalStringListSnapshotValueMatches(
                    spectatorEffect,
                    "participantDependencyObjectIds",
                    authoritativeEffect.ParticipantDependencyObjectIds))
            {
                participantDependencyObjectIdsMatch = false;
            }

            if (!OptionalStringListSnapshotValueMatches(
                    spectatorEffect,
                    "deferredLayerEngineResiduals",
                    authoritativeEffect.DeferredLayerEngineResiduals))
            {
                deferredLayerEngineResidualsMatch = false;
            }
        }

        if (!effectIdsMatch)
        {
            errors.Add("spectator replay frame timing continuous effect ids disagree with authoritative state continuous effect ids");
        }

        if (!scopesMatch)
        {
            errors.Add("spectator replay frame timing continuous effect scopes disagree with authoritative state continuous effect scopes");
        }

        if (!layersMatch)
        {
            errors.Add("spectator replay frame timing continuous effect layers disagree with authoritative state continuous effect layers");
        }

        if (!durationsMatch)
        {
            errors.Add("spectator replay frame timing continuous effect durations disagree with authoritative state continuous effect durations");
        }

        if (!targetObjectIdsMatch)
        {
            errors.Add("spectator replay frame timing continuous effect target objects disagree with authoritative state continuous effect target objects");
        }

        if (!sourceObjectIdsMatch)
        {
            errors.Add("spectator replay frame timing continuous effect source objects disagree with authoritative state continuous effect source objects");
        }

        if (!powerDeltasMatch)
        {
            errors.Add("spectator replay frame timing continuous effect power deltas disagree with authoritative state continuous effect power deltas");
        }

        if (!basePowersMatch)
        {
            errors.Add("spectator replay frame timing continuous effect base powers disagree with authoritative state continuous effect base powers");
        }

        if (!effectivePowersMatch)
        {
            errors.Add("spectator replay frame timing continuous effect effective powers disagree with authoritative state continuous effect effective powers");
        }

        if (!sequencesMatch)
        {
            errors.Add("spectator replay frame timing continuous effect sequences disagree with authoritative state continuous effect sequences");
        }

        if (!effectKindsMatch)
        {
            errors.Add("spectator replay frame timing continuous effect kinds disagree with authoritative state continuous effect kinds");
        }

        if (!sourceCardNumbersMatch)
        {
            errors.Add("spectator replay frame timing continuous effect source card numbers disagree with authoritative state continuous effect source card numbers");
        }

        if (!sourcePathsMatch)
        {
            errors.Add("spectator replay frame timing continuous effect source paths disagree with authoritative state continuous effect source paths");
        }

        if (!layerEngineStatusesMatch)
        {
            errors.Add("spectator replay frame timing continuous effect layer engine statuses disagree with authoritative state continuous effect layer engine statuses");
        }

        if (!requestedPowerDeltasMatch)
        {
            errors.Add("spectator replay frame timing continuous effect requested power deltas disagree with authoritative state continuous effect requested power deltas");
        }

        if (!appliedPowerDeltasMatch)
        {
            errors.Add("spectator replay frame timing continuous effect applied power deltas disagree with authoritative state continuous effect applied power deltas");
        }

        if (!minimumPowersMatch)
        {
            errors.Add("spectator replay frame timing continuous effect minimum powers disagree with authoritative state continuous effect minimum powers");
        }

        if (!resultingPowersMatch)
        {
            errors.Add("spectator replay frame timing continuous effect resulting powers disagree with authoritative state continuous effect resulting powers");
        }

        if (!appliedOrdersMatch)
        {
            errors.Add("spectator replay frame timing continuous effect applied orders disagree with authoritative state continuous effect applied orders");
        }

        if (!sourceOrdersMatch)
        {
            errors.Add("spectator replay frame timing continuous effect source orders disagree with authoritative state continuous effect source orders");
        }

        if (!conditionsMatch)
        {
            errors.Add("spectator replay frame timing continuous effect conditions disagree with authoritative state continuous effect conditions");
        }

        if (!lifecyclesMatch)
        {
            errors.Add("spectator replay frame timing continuous effect lifecycles disagree with authoritative state continuous effect lifecycles");
        }

        if (!participantObjectIdsMatch)
        {
            errors.Add("spectator replay frame timing continuous effect participant object ids disagree with authoritative state continuous effect participant object ids");
        }

        if (!sourceDependencyObjectIdsMatch)
        {
            errors.Add("spectator replay frame timing continuous effect source dependency object ids disagree with authoritative state continuous effect source dependency object ids");
        }

        if (!targetDependencyObjectIdsMatch)
        {
            errors.Add("spectator replay frame timing continuous effect target dependency object ids disagree with authoritative state continuous effect target dependency object ids");
        }

        if (!participantDependencyObjectIdsMatch)
        {
            errors.Add("spectator replay frame timing continuous effect participant dependency object ids disagree with authoritative state continuous effect participant dependency object ids");
        }

        if (!deferredLayerEngineResidualsMatch)
        {
            errors.Add("spectator replay frame timing continuous effect deferred LayerEngine residuals disagree with authoritative state continuous effect deferred LayerEngine residuals");
        }
    }

    private static void AddSpectatorContinuousEffectCountMismatch(
        int spectatorCount,
        int authoritativeCount,
        List<string> errors)
    {
        errors.Add(
            $"spectator replay frame timing continuous effect count {spectatorCount} does not match authoritative state continuous effect count {authoritativeCount}; {FormatExpectedActualForRecovery(authoritativeCount, spectatorCount)}");
    }

    private static IReadOnlyDictionary<string, ContinuousEffectState> BuildAuthoritativeContinuousEffectsById(
        IReadOnlyList<ContinuousEffectState> authoritativeEffects)
    {
        var authoritativeEffectsById = new Dictionary<string, ContinuousEffectState>(StringComparer.Ordinal);
        foreach (var authoritativeEffect in authoritativeEffects)
        {
            if (string.IsNullOrWhiteSpace(authoritativeEffect.EffectId))
            {
                continue;
            }

            var normalizedEffectId = authoritativeEffect.EffectId.Trim();
            if (!authoritativeEffectsById.ContainsKey(normalizedEffectId))
            {
                authoritativeEffectsById.Add(normalizedEffectId, authoritativeEffect);
            }
        }

        return authoritativeEffectsById;
    }

    private static void ReportMissingSpectatorContinuousEffectAuthoritativeKeySet(
        IReadOnlyList<ContinuousEffectState> authoritativeEffects,
        List<string> errors)
    {
        ValidateSpectatorContinuousEffectAuthoritativeKeySet(
            Array.Empty<object?>(),
            BuildAuthoritativeContinuousEffectsById(authoritativeEffects),
            errors);
    }

    private static void ValidateSpectatorContinuousEffectAuthoritativeKeySet(
        IReadOnlyList<object?> effectPayloads,
        IReadOnlyDictionary<string, ContinuousEffectState> authoritativeEffectsById,
        List<string> errors)
    {
        const string payloadLabel = "spectator replay frame timing continuous effect item";
        var actualEffectIds = new HashSet<string>(StringComparer.Ordinal);
        foreach (var effectPayload in effectPayloads)
        {
            if (!IsSnapshotPlayerPayloadObject(effectPayload)
                || !TryReadObjectString(effectPayload, "effectId", out var effectId)
                || string.IsNullOrWhiteSpace(effectId))
            {
                continue;
            }

            var normalizedEffectId = effectId.Trim();
            actualEffectIds.Add(normalizedEffectId);
            if (!authoritativeEffectsById.ContainsKey(normalizedEffectId))
            {
                errors.Add(
                    $"{payloadLabel} effect id {normalizedEffectId} is not present in authoritative state continuous effects");
            }
        }

        foreach (var authoritativeEffectId in authoritativeEffectsById.Keys.OrderBy(id => id, StringComparer.Ordinal))
        {
            if (!actualEffectIds.Contains(authoritativeEffectId))
            {
                errors.Add(
                    $"{payloadLabel} effect id {authoritativeEffectId} is required by authoritative state continuous effects");
            }
        }
    }

    private static void ValidateSpectatorContinuousEffectKeyedAuthoritativeValues(
        IReadOnlyList<object?> effectPayloads,
        IReadOnlyDictionary<string, ContinuousEffectState> authoritativeEffectsById,
        List<string> errors)
    {
        foreach (var effectPayload in effectPayloads)
        {
            if (!IsSnapshotPlayerPayloadObject(effectPayload)
                || !TryReadObjectString(effectPayload, "effectId", out var effectId)
                || string.IsNullOrWhiteSpace(effectId))
            {
                continue;
            }

            var normalizedEffectId = effectId.Trim();
            if (!authoritativeEffectsById.TryGetValue(normalizedEffectId, out var authoritativeEffect))
            {
                continue;
            }

            ValidateSpectatorContinuousEffectKeyedStringValue(
                effectPayload,
                "scope",
                "scope",
                authoritativeEffect.Scope,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedStringValue(
                effectPayload,
                "layer",
                "layer",
                authoritativeEffect.Layer,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedStringValue(
                effectPayload,
                "duration",
                "duration",
                authoritativeEffect.Duration,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalStringValue(
                effectPayload,
                "targetObjectId",
                "target object id",
                authoritativeEffect.TargetObjectId,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalStringValue(
                effectPayload,
                "sourceObjectId",
                "source object id",
                authoritativeEffect.SourceObjectId,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedIntValue(
                effectPayload,
                "powerDelta",
                "power delta",
                authoritativeEffect.PowerDelta,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedIntValue(
                effectPayload,
                "basePower",
                "base power",
                authoritativeEffect.BasePower,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedIntValue(
                effectPayload,
                "effectivePower",
                "effective power",
                authoritativeEffect.EffectivePower,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedIntValue(
                effectPayload,
                "sequence",
                "sequence",
                authoritativeEffect.Sequence,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalStringValue(
                effectPayload,
                "effectKind",
                "effect kind",
                authoritativeEffect.EffectKind,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalStringValue(
                effectPayload,
                "sourceCardNo",
                "source card number",
                authoritativeEffect.SourceCardNo,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalStringValue(
                effectPayload,
                "sourcePath",
                "source path",
                authoritativeEffect.SourcePath,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalStringValue(
                effectPayload,
                "layerEngineStatus",
                "layer engine status",
                authoritativeEffect.IsLayerEngineFoundationOnly ? "FOUNDATION_ONLY" : null,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalIntValue(
                effectPayload,
                "requestedPowerDelta",
                "requested power delta",
                authoritativeEffect.RequestedPowerDelta,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalIntValue(
                effectPayload,
                "appliedPowerDelta",
                "applied power delta",
                authoritativeEffect.AppliedPowerDelta,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalIntValue(
                effectPayload,
                "minimumPower",
                "minimum power",
                authoritativeEffect.MinimumPower,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalIntValue(
                effectPayload,
                "resultingPower",
                "resulting power",
                authoritativeEffect.ResultingPower,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalIntValue(
                effectPayload,
                "appliedOrder",
                "applied order",
                authoritativeEffect.AppliedOrder,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalIntValue(
                effectPayload,
                "sourceOrder",
                "source order",
                authoritativeEffect.SourceOrder,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalStringValue(
                effectPayload,
                "condition",
                "condition",
                authoritativeEffect.Condition,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalStringValue(
                effectPayload,
                "lifecycle",
                "lifecycle",
                authoritativeEffect.Lifecycle,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalStringListValue(
                effectPayload,
                "participantObjectIds",
                "participant object ids",
                authoritativeEffect.ParticipantObjectIds,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalStringListValue(
                effectPayload,
                "sourceDependencyObjectIds",
                "source dependency object ids",
                authoritativeEffect.SourceDependencyObjectIds,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalStringListValue(
                effectPayload,
                "targetDependencyObjectIds",
                "target dependency object ids",
                authoritativeEffect.TargetDependencyObjectIds,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalStringListValue(
                effectPayload,
                "participantDependencyObjectIds",
                "participant dependency object ids",
                authoritativeEffect.ParticipantDependencyObjectIds,
                normalizedEffectId,
                errors);
            ValidateSpectatorContinuousEffectKeyedOptionalStringListValue(
                effectPayload,
                "deferredLayerEngineResiduals",
                "deferred LayerEngine residuals",
                authoritativeEffect.DeferredLayerEngineResiduals,
                normalizedEffectId,
                errors);
        }
    }

    private static void ValidateSpectatorContinuousEffectKeyedStringValue(
        object? effectPayload,
        string key,
        string fieldLabel,
        string expected,
        string effectId,
        List<string> errors)
    {
        if (!TryReadObjectString(effectPayload, key, out var actual))
        {
            AddSpectatorContinuousEffectKeyedValueMismatch(
                fieldLabel,
                effectId,
                FormatExpectedActualForRecovery(expected, FormatUnreadableObjectValue(effectPayload, key)),
                errors);
            return;
        }

        if (!string.Equals(actual, expected, StringComparison.Ordinal))
        {
            AddSpectatorContinuousEffectKeyedValueMismatch(
                fieldLabel,
                effectId,
                FormatExpectedActualForRecovery(expected, actual),
                errors);
        }
    }

    private static void ValidateSpectatorContinuousEffectKeyedOptionalStringValue(
        object? effectPayload,
        string key,
        string fieldLabel,
        string? expected,
        string effectId,
        List<string> errors)
    {
        var expectedText = expected ?? string.Empty;
        if (!TryReadObjectValue(effectPayload, key, out var value))
        {
            if (string.IsNullOrEmpty(expectedText))
            {
                return;
            }

            AddSpectatorContinuousEffectKeyedValueMismatch(
                fieldLabel,
                effectId,
                FormatExpectedActualForRecovery(expectedText, "<missing>"),
                errors);
            return;
        }

        if (!TryReadOptionalStringValue(value, out var actual)
            || !string.Equals(actual, expectedText, StringComparison.Ordinal))
        {
            AddSpectatorContinuousEffectKeyedValueMismatch(
                fieldLabel,
                effectId,
                FormatExpectedActualForRecovery(
                    expectedText,
                    TryReadOptionalStringValue(value, out var readableActual) ? readableActual : "<unreadable>"),
                errors);
        }
    }

    private static void ValidateSpectatorContinuousEffectKeyedIntValue(
        object? effectPayload,
        string key,
        string fieldLabel,
        int expected,
        string effectId,
        List<string> errors)
    {
        if (!TryReadObjectInt(effectPayload, key, out var actual))
        {
            AddSpectatorContinuousEffectKeyedValueMismatch(
                fieldLabel,
                effectId,
                FormatExpectedActualForRecovery(expected, FormatUnreadableObjectValue(effectPayload, key)),
                errors);
            return;
        }

        if (actual != expected)
        {
            AddSpectatorContinuousEffectKeyedValueMismatch(
                fieldLabel,
                effectId,
                FormatExpectedActualForRecovery(expected, actual),
                errors);
        }
    }

    private static void ValidateSpectatorContinuousEffectKeyedOptionalIntValue(
        object? effectPayload,
        string key,
        string fieldLabel,
        int? expected,
        string effectId,
        List<string> errors)
    {
        if (!TryReadObjectValue(effectPayload, key, out var value))
        {
            if (!expected.HasValue)
            {
                return;
            }

            AddSpectatorContinuousEffectKeyedValueMismatch(
                fieldLabel,
                effectId,
                FormatExpectedActualForRecovery(expected.Value, "<missing>"),
                errors);
            return;
        }

        if (!expected.HasValue)
        {
            AddSpectatorContinuousEffectKeyedValueMismatch(
                fieldLabel,
                effectId,
                FormatExpectedActualForRecovery("<empty>", FormatReadableIntValue(value)),
                errors);
            return;
        }

        if (!TryReadIntValue(value, out var actual)
            || actual != expected.Value)
        {
            AddSpectatorContinuousEffectKeyedValueMismatch(
                fieldLabel,
                effectId,
                FormatExpectedActualForRecovery(
                    expected.Value,
                    TryReadIntValue(value, out var readableActual) ? readableActual : "<unreadable>"),
                errors);
        }
    }

    private static void ValidateSpectatorContinuousEffectKeyedOptionalStringListValue(
        object? effectPayload,
        string key,
        string fieldLabel,
        IReadOnlyList<string>? expected,
        string effectId,
        List<string> errors)
    {
        IReadOnlyList<string> expectedValues = expected ?? [];
        if (!TryReadObjectValue(effectPayload, key, out var value))
        {
            if (expectedValues.Count == 0)
            {
                return;
            }

            AddSpectatorContinuousEffectKeyedValueMismatch(
                fieldLabel,
                effectId,
                FormatExpectedActualForRecovery(expectedValues, "<missing>"),
                errors);
            return;
        }

        if (!TryReadStringListValue(value, out var actual)
            || !StringListsEqual(actual, expectedValues))
        {
            AddSpectatorContinuousEffectKeyedValueMismatch(
                fieldLabel,
                effectId,
                FormatExpectedActualForRecovery(
                    expectedValues,
                    TryReadStringListValue(value, out var readableActual) ? readableActual : "<unreadable>"),
                errors);
        }
    }

    private static void AddSpectatorContinuousEffectKeyedValueMismatch(
        string fieldLabel,
        string effectId,
        string detail,
        List<string> errors)
    {
        errors.Add(
            $"spectator replay frame timing continuous effect item {fieldLabel} does not match authoritative state continuous effect {fieldLabel} for effect id {effectId}; {detail}");
    }

    private static string FormatExpectedActualForRecovery(object? expected, object? actual)
    {
        return $"expected {FormatRecoveryDiagnosticValue(expected)} but got {FormatRecoveryDiagnosticValue(actual)}";
    }

    private static string FormatRecoveryDiagnosticValue(object? value)
    {
        return value switch
        {
            null => "<empty>",
            string text => text.Length == 0 ? "<empty>" : text,
            int number => number.ToString(CultureInfo.InvariantCulture),
            long number => number.ToString(CultureInfo.InvariantCulture),
            bool flag => flag ? "true" : "false",
            IReadOnlyDictionary<string, int> values => FormatRecoveryDiagnosticIntDictionary(values),
            IReadOnlyDictionary<string, IReadOnlyList<string>> values => FormatRecoveryDiagnosticStringListDictionary(values),
            IReadOnlyList<BattleRequiredAssignmentView> values => FormatRecoveryDiagnosticRequiredAssignments(values),
            IReadOnlyList<string> values => values.Count == 0 ? "[]" : $"[{string.Join(", ", values)}]",
            IEnumerable<string> values => FormatRecoveryDiagnosticValue(values.ToArray()),
            _ => value.ToString() ?? "<unreadable>"
        };
    }

    private static string FormatRecoveryDiagnosticIntDictionary(IReadOnlyDictionary<string, int> values)
    {
        var formattedEntries = values
            .OrderBy(entry => entry.Key, StringComparer.Ordinal)
            .Select(entry => $"{entry.Key}: {entry.Value.ToString(CultureInfo.InvariantCulture)}");

        return values.Count == 0
            ? "{}"
            : $"{{{string.Join(", ", formattedEntries)}}}";
    }

    private static string FormatRecoveryDiagnosticStringListDictionary(
        IReadOnlyDictionary<string, IReadOnlyList<string>> values)
    {
        var formattedEntries = values
            .OrderBy(entry => entry.Key, StringComparer.Ordinal)
            .Select(entry => $"{entry.Key}: {FormatRecoveryDiagnosticValue(entry.Value)}");

        return values.Count == 0
            ? "{}"
            : $"{{{string.Join(", ", formattedEntries)}}}";
    }

    private static string FormatRecoveryDiagnosticRequiredAssignments(
        IReadOnlyList<BattleRequiredAssignmentView> values)
    {
        if (values.Count == 0)
        {
            return "[]";
        }

        var formattedAssignments = values.Select(assignment =>
            "{"
            + $"sourceObjectId: {FormatRecoveryDiagnosticValue(assignment.SourceObjectId)}, "
            + $"damage: {FormatRecoveryDiagnosticValue(assignment.Damage)}, "
            + $"legalTargetObjectIds: {FormatRecoveryDiagnosticValue(assignment.LegalTargetObjectIds)}"
            + "}");

        return $"[{string.Join(", ", formattedAssignments)}]";
    }

    private static string FormatUnreadableObjectValue(object? payload, string key)
    {
        return TryReadObjectValue(payload, key, out _) ? "<unreadable>" : "<missing>";
    }

    private static object FormatReadableIntValue(object? value)
    {
        return TryReadIntValue(value, out var actual) ? actual : "<unreadable>";
    }

    private static (string? EffectId, int? Sequence) ValidateSpectatorContinuousEffectPayloadValues(
        object? effectPayload,
        IReadOnlySet<string> knownObjectIds,
