    {
        if (string.IsNullOrWhiteSpace(objectId))
        {
            return;
        }

        var normalizedObjectId = objectId.Trim();
        if (!knownObjectIds.Contains(normalizedObjectId))
        {
            errors.Add($"{objectLabel} {normalizedObjectId} is missing from {knownObjectLabel}");
        }
    }

    private static (string? EffectId, int? Sequence) ValidateContinuousEffectScalarPayloadValues(
        object? effectPayload,
        string effectLabel,
        List<string> errors)
    {
        var effectId = ValidateSnapshotPayloadRequiredStringValue(
            effectPayload,
            "effectId",
            effectLabel,
            "effect id",
            errors);
        var scope = ValidateSnapshotPayloadRequiredStringValue(
            effectPayload,
            "scope",
            effectLabel,
            "scope",
            errors,
            IsKnownContinuousEffectScope);
        var layer = ValidateSnapshotPayloadRequiredStringValue(
            effectPayload,
            "layer",
            effectLabel,
            "layer",
            errors,
            IsKnownContinuousEffectLayer);
        ValidateContinuousEffectLayerScopeConsistency(effectLabel, scope, layer, errors);
        var duration = ValidateSnapshotPayloadRequiredStringValue(
            effectPayload,
            "duration",
            effectLabel,
            "duration",
            errors,
            IsKnownContinuousEffectDuration);
        ValidateContinuousEffectLayerDurationConsistency(effectLabel, layer, duration, errors);
        ValidateContinuousEffectStaticAuraScopeDurationConsistency(effectLabel, scope, layer, duration, errors);
        var targetObjectId = ValidateSnapshotPayloadRequiredNullableStringValue(
            effectPayload,
            "targetObjectId",
            effectLabel,
            "target object id",
            errors);
        ValidateContinuousEffectTargetObjectConsistency(effectLabel, scope, layer, targetObjectId, errors);
        var sourceObjectId = ValidateSnapshotPayloadRequiredNullableStringValue(
            effectPayload,
            "sourceObjectId",
            effectLabel,
            "source object id",
            errors);
        ValidateContinuousEffectSourceObjectConsistency(effectLabel, scope, layer, sourceObjectId, errors);
        ValidateContinuousEffectStaticAuraEffectIdConsistency(
            effectLabel,
            effectId,
            scope,
            layer,
            duration,
            targetObjectId,
            sourceObjectId,
            errors);
        ValidateContinuousEffectStaticAuraObjectSourceTargetConsistency(
            effectLabel,
            scope,
            layer,
            duration,
            targetObjectId,
            sourceObjectId,
            errors);
        var powerDelta = ValidateSnapshotPayloadRequiredIntValue(
            effectPayload,
            "powerDelta",
            effectLabel,
            "power delta",
            errors);
        var basePower = ValidateSnapshotPayloadRequiredIntValue(
            effectPayload,
            "basePower",
            effectLabel,
            "base power",
            errors);
        var effectivePower = ValidateSnapshotPayloadRequiredIntValue(
            effectPayload,
            "effectivePower",
            effectLabel,
            "effective power",
            errors);
        ValidateContinuousEffectRuleTextPowerScalarConsistency(
            effectLabel,
            scope,
            layer,
            powerDelta,
            basePower,
            effectivePower,
            errors);
        ValidateContinuousEffectPowerModifierPowerDeltaConsistency(
            effectLabel,
            scope,
            layer,
            powerDelta,
            errors);
        ValidateContinuousEffectStaticAuraPowerDeltaConsistency(
            effectPayload,
            effectLabel,
            scope,
            layer,
            duration,
            powerDelta,
            errors);
        ValidateContinuousEffectStaticAuraBattlefieldPowerScalarConsistency(
            effectLabel,
            scope,
            layer,
            duration,
            powerDelta,
            basePower,
            effectivePower,
            errors);
        var sequence = ValidateSnapshotPayloadRequiredPositiveIntValue(
            effectPayload,
            "sequence",
            effectLabel,
            "sequence",
            errors);
        var effectKind = ValidateSnapshotPayloadOptionalStringValue(
            effectPayload,
            "effectKind",
            effectLabel,
            "effect kind",
            errors,
            rejectEmptyString: true);
        var sourceCardNo = ValidateSnapshotPayloadOptionalStringValue(
            effectPayload,
            "sourceCardNo",
            effectLabel,
            "source card no",
            errors,
            rejectEmptyString: true);
        var sourcePath = ValidateSnapshotPayloadOptionalStringValue(
            effectPayload,
            "sourcePath",
            effectLabel,
            "source path",
            errors,
            rejectEmptyString: true);
        var layerEngineStatus = ValidateSnapshotPayloadOptionalStringValue(
            effectPayload,
            "layerEngineStatus",
            effectLabel,
            "layer engine status",
            errors,
            IsKnownContinuousEffectLayerEngineStatus,
            rejectEmptyString: true);
        ValidateContinuousEffectLayerEngineResidualConsistency(
            effectPayload,
            effectLabel,
            layer,
            layerEngineStatus,
            errors);
        ValidateContinuousEffectPowerModifierFoundationResidualCanonicality(
            effectPayload,
            effectLabel,
            scope,
            layer,
            layerEngineStatus,
            errors);
        ValidateContinuousEffectStaticAuraFoundationResidualCanonicality(
            effectPayload,
            effectLabel,
            scope,
            layer,
            layerEngineStatus,
            errors);
        var requestedPowerDelta = ValidateSnapshotPayloadOptionalIntValue(
            effectPayload,
            "requestedPowerDelta",
            effectLabel,
            "requested power delta",
            errors);
        var appliedPowerDelta = ValidateSnapshotPayloadOptionalIntValue(
            effectPayload,
            "appliedPowerDelta",
            effectLabel,
            "applied power delta",
            errors);
        ValidateContinuousEffectAppliedPowerDeltaConsistency(effectLabel, powerDelta, appliedPowerDelta, errors);
        var minimumPower = ValidateSnapshotPayloadOptionalNonNegativeIntValue(
            effectPayload,
            "minimumPower",
            effectLabel,
            "minimum power",
            errors);
        var resultingPower = ValidateSnapshotPayloadOptionalIntValue(
            effectPayload,
            "resultingPower",
            effectLabel,
            "resulting power",
            errors);
        ValidateContinuousEffectPowerFloorConsistency(effectLabel, minimumPower, resultingPower, errors);
        var appliedOrder = ValidateSnapshotPayloadOptionalPositiveIntValue(
            effectPayload,
            "appliedOrder",
            effectLabel,
            "applied order",
            errors);
        var sourceOrder = ValidateSnapshotPayloadOptionalPositiveIntValue(
            effectPayload,
            "sourceOrder",
            effectLabel,
            "source order",
            errors);
        ValidateContinuousEffectRuleTextModifierScalarAbsence(
            effectLabel,
            scope,
            layer,
            requestedPowerDelta,
            appliedPowerDelta,
            minimumPower,
            resultingPower,
            appliedOrder,
            sourceOrder,
            errors);
        ValidateContinuousEffectRuleTextRuntimeMetadataAbsence(
            effectPayload,
            effectLabel,
            scope,
            layer,
            effectKind,
            sourceCardNo,
            sourcePath,
            layerEngineStatus,
            errors);
        ValidateContinuousEffectPowerModifierFoundationMetadataConsistency(
            effectPayload,
            effectLabel,
            scope,
            layer,
            layerEngineStatus,
            errors);
        ValidateContinuousEffectPowerModifierFoundationSourceCardConsistency(
            effectPayload,
            effectLabel,
            scope,
            layer,
            sourceCardNo,
            sourceObjectId,
            layerEngineStatus,
            errors);
        ValidateContinuousEffectPowerModifierFoundationModifierScalarCompleteness(
            effectPayload,
            effectLabel,
            scope,
            layer,
            sourceObjectId,
            requestedPowerDelta,
            appliedPowerDelta,
            minimumPower,
            resultingPower,
            appliedOrder,
            layerEngineStatus,
            errors);
        ValidateContinuousEffectPowerModifierFoundationLegacyRemainderMetadataConsistency(
            effectPayload,
            effectLabel,
            scope,
            layer,
            effectKind,
            sourcePath,
            sourceObjectId,
            requestedPowerDelta,
            appliedPowerDelta,
            minimumPower,
            resultingPower,
            appliedOrder,
            layerEngineStatus,
            errors);
        ValidateContinuousEffectPowerModifierFoundationResultingPowerConsistency(
            effectPayload,
            effectLabel,
            scope,
            layer,
            effectivePower,
            resultingPower,
            layerEngineStatus,
            errors);
        ValidateContinuousEffectPowerModifierNonFoundationMetadataAbsence(
            effectPayload,
            effectLabel,
            scope,
            layer,
            effectKind,
            sourceCardNo,
            sourcePath,
            sourceObjectId,
            layerEngineStatus,
            errors);
        ValidateContinuousEffectPowerModifierNonFoundationModifierScalarAbsence(
            effectPayload,
            effectLabel,
            scope,
            layer,
            requestedPowerDelta,
            appliedPowerDelta,
            minimumPower,
            resultingPower,
            appliedOrder,
            layerEngineStatus,
            errors);
        ValidateContinuousEffectPowerModifierNonFoundationPowerScalarConsistency(
            effectPayload,
            effectLabel,
            scope,
            layer,
            powerDelta,
            basePower,
            effectivePower,
            layerEngineStatus,
            errors);
        ValidateContinuousEffectPowerModifierSourceOrderConsistency(
            effectLabel,
            scope,
            layer,
            sourceObjectId,
            sourceOrder,
            errors);
        var condition = ValidateSnapshotPayloadOptionalStringValue(
            effectPayload,
            "condition",
            effectLabel,
            "condition",
            errors,
            rejectEmptyString: true);
        var lifecycle = ValidateSnapshotPayloadOptionalStringValue(
            effectPayload,
            "lifecycle",
            effectLabel,
            "lifecycle",
            errors,
            rejectEmptyString: true);
        ValidateContinuousEffectStaticAuraMetadataConsistency(
            effectLabel,
            scope,
            layer,
            duration,
            effectKind,
            sourceCardNo,
            sourcePath,
            condition,
            lifecycle,
            errors);
        ValidateContinuousEffectNonStaticAuraParticipantListAbsence(effectPayload, effectLabel, layer, errors);
        ValidateContinuousEffectNonStaticAuraDependencyListAbsence(effectPayload, effectLabel, layer, errors);
        ValidateContinuousEffectNonStaticAuraStaticMetadataAbsence(effectPayload, effectLabel, layer, errors);
        return (effectId, sequence);
    }

    private static bool IsContinuousEffectLayerScopeValid(string scope, string layer)
    {
        if (string.Equals(layer, ContinuousEffectLayers.PowerModifier, StringComparison.Ordinal))
        {
            return string.Equals(scope, "OBJECT", StringComparison.Ordinal);
        }

        if (string.Equals(layer, ContinuousEffectLayers.RuleText, StringComparison.Ordinal))
        {
            return string.Equals(scope, "GLOBAL", StringComparison.Ordinal)
                || string.Equals(scope, "OBJECT", StringComparison.Ordinal);
        }

        return string.Equals(scope, "OBJECT", StringComparison.Ordinal)
            || string.Equals(scope, "BATTLEFIELD", StringComparison.Ordinal);
    }

    private static void ValidateContinuousEffectLayerScopeConsistency(
        string effectLabel,
        string? scope,
        string? layer,
        List<string> errors)
    {
        if (scope is null
            || layer is null
            || !IsKnownContinuousEffectScope(scope)
            || !IsKnownContinuousEffectLayer(layer))
        {
            return;
        }

        if (IsContinuousEffectLayerScopeValid(scope, layer))
        {
            return;
        }

        if (string.Equals(layer, ContinuousEffectLayers.PowerModifier, StringComparison.Ordinal))
        {
            errors.Add($"{effectLabel} POWER_MODIFIER scope {scope} is invalid");
            return;
        }

        if (string.Equals(layer, ContinuousEffectLayers.RuleText, StringComparison.Ordinal))
        {
            errors.Add($"{effectLabel} RULE_TEXT scope {scope} is invalid");
            return;
        }

        errors.Add($"{effectLabel} static aura scope {scope} is invalid");
    }

    private static void ValidateContinuousEffectTargetObjectConsistency(
        string effectLabel,
        string? scope,
        string? layer,
        string? targetObjectId,
        List<string> errors)
    {
        if (scope is null
            || layer is null
            || !IsKnownContinuousEffectScope(scope)
            || !IsKnownContinuousEffectLayer(layer)
            || !IsContinuousEffectLayerScopeValid(scope, layer))
        {
            return;
        }

        if (string.Equals(layer, ContinuousEffectLayers.RuleText, StringComparison.Ordinal)
            && string.Equals(scope, "GLOBAL", StringComparison.Ordinal))
        {
            if (targetObjectId is not null)
            {
                errors.Add($"{effectLabel} global rule text target object id must be absent");
            }

            return;
        }

        if (targetObjectId is not null)
        {
            return;
        }

        if (string.Equals(layer, ContinuousEffectLayers.StaticAura, StringComparison.Ordinal))
        {
            errors.Add($"{effectLabel} static aura target object id is required");
            return;
        }

        errors.Add($"{effectLabel} {layer} target object id is required");
    }

    private static void ValidateContinuousEffectSourceObjectConsistency(
        string effectLabel,
        string? scope,
        string? layer,
        string? sourceObjectId,
        List<string> errors)
    {
        if (scope is null
            || layer is null
            || !IsKnownContinuousEffectScope(scope)
            || !IsKnownContinuousEffectLayer(layer)
            || !IsContinuousEffectLayerScopeValid(scope, layer))
        {
            return;
        }

        if (string.Equals(layer, ContinuousEffectLayers.RuleText, StringComparison.Ordinal)
            && string.Equals(scope, "GLOBAL", StringComparison.Ordinal))
        {
            if (sourceObjectId is not null)
            {
                errors.Add($"{effectLabel} global rule text source object id must be absent");
            }

            return;
        }

        if (string.Equals(layer, ContinuousEffectLayers.StaticAura, StringComparison.Ordinal)
            && sourceObjectId is null)
        {
            errors.Add($"{effectLabel} static aura source object id is required");
        }
    }

    private static void ValidateContinuousEffectStaticAuraEffectIdConsistency(
        string effectLabel,
        string? effectId,
        string? scope,
        string? layer,
        string? duration,
        string? targetObjectId,
        string? sourceObjectId,
        List<string> errors)
    {
        if (effectId is null
            || scope is null
            || layer is null
            || duration is null
            || targetObjectId is null
            || sourceObjectId is null
            || !IsKnownContinuousEffectScope(scope)
            || !IsKnownContinuousEffectLayer(layer)
            || !IsKnownContinuousEffectDuration(duration)
            || !string.Equals(layer, ContinuousEffectLayers.StaticAura, StringComparison.Ordinal)
            || !IsContinuousEffectLayerScopeValid(scope, layer))
        {
            return;
        }

        if (string.Equals(scope, "OBJECT", StringComparison.Ordinal))
        {
            if (!string.Equals(duration, "WHILE_SOURCE_ON_PUBLIC_FIELD", StringComparison.Ordinal)
                || !string.Equals(targetObjectId, sourceObjectId, StringComparison.Ordinal))
            {
                return;
            }

            ValidateContinuousEffectStaticAuraExpectedEffectId(
                effectLabel,
                effectId,
                $"STATIC_AURA:FRIENDLY_EQUIPMENT_POWER:{sourceObjectId}",
                "object static aura effect id",
                errors);
            return;
        }

        if (string.Equals(scope, "BATTLEFIELD", StringComparison.Ordinal)
            && string.Equals(duration, "WHILE_SOURCE_BATTLEFIELD_AND_PARTICIPANT_AT_BATTLEFIELD", StringComparison.Ordinal))
        {
            ValidateContinuousEffectStaticAuraExpectedEffectId(
                effectLabel,
                effectId,
                $"STATIC_AURA:BATTLEFIELD_ALL_UNITS_POWER_PLUS_ONE:{sourceObjectId}:{targetObjectId}",
                "battlefield static aura effect id",
                errors);
        }
    }

    private static void ValidateContinuousEffectStaticAuraExpectedEffectId(
        string effectLabel,
        string actual,
        string expected,
        string diagnosticLabel,
        List<string> errors)
    {
        if (string.Equals(actual, expected, StringComparison.Ordinal))
        {
            return;
        }

        errors.Add($"{effectLabel} {diagnosticLabel} must be {expected}");
    }

    private static void ValidateContinuousEffectStaticAuraObjectSourceTargetConsistency(
        string effectLabel,
        string? scope,
        string? layer,
        string? duration,
        string? targetObjectId,
        string? sourceObjectId,
        List<string> errors)
    {
        if (scope is null
            || layer is null
            || duration is null
            || targetObjectId is null
            || sourceObjectId is null
            || !IsKnownContinuousEffectScope(scope)
            || !IsKnownContinuousEffectLayer(layer)
            || !IsKnownContinuousEffectDuration(duration)
            || !string.Equals(scope, "OBJECT", StringComparison.Ordinal)
            || !string.Equals(layer, ContinuousEffectLayers.StaticAura, StringComparison.Ordinal)
            || !string.Equals(duration, "WHILE_SOURCE_ON_PUBLIC_FIELD", StringComparison.Ordinal)
            || !IsContinuousEffectLayerScopeValid(scope, layer)
            || string.Equals(targetObjectId, sourceObjectId, StringComparison.Ordinal))
        {
            return;
        }

        errors.Add(
            $"{effectLabel} object static aura target object id {targetObjectId} must match source object id {sourceObjectId}");
    }

    private static void ValidateContinuousEffectStaticAuraMetadataConsistency(
        string effectLabel,
        string? scope,
        string? layer,
        string? duration,
        string? effectKind,
        string? sourceCardNo,
        string? sourcePath,
        string? condition,
        string? lifecycle,
        List<string> errors)
    {
        if (!string.Equals(layer, ContinuousEffectLayers.StaticAura, StringComparison.Ordinal))
        {
            return;
        }

        if (effectKind is null)
        {
            errors.Add($"{effectLabel} static aura effect kind is required");
        }

        if (sourceCardNo is null)
        {
            errors.Add($"{effectLabel} static aura source card no is required");
        }

        if (sourcePath is null)
        {
            errors.Add($"{effectLabel} static aura source path is required");
        }

        if (condition is null)
        {
            errors.Add($"{effectLabel} static aura condition is required");
        }

        if (lifecycle is null)
        {
            errors.Add($"{effectLabel} static aura lifecycle is required");
        }

        ValidateContinuousEffectStaticAuraMetadataValueConsistency(
            effectLabel,
            scope,
            layer,
            duration,
            effectKind,
            sourceCardNo,
            sourcePath,
            condition,
            lifecycle,
            errors);
    }

    private static void ValidateContinuousEffectStaticAuraMetadataValueConsistency(
        string effectLabel,
        string? scope,
        string? layer,
        string? duration,
        string? effectKind,
        string? sourceCardNo,
        string? sourcePath,
        string? condition,
        string? lifecycle,
        List<string> errors)
    {
        if (scope is null
            || layer is null
            || duration is null
            || !IsKnownContinuousEffectScope(scope)
            || !IsKnownContinuousEffectLayer(layer)
            || !IsKnownContinuousEffectDuration(duration)
            || !string.Equals(layer, ContinuousEffectLayers.StaticAura, StringComparison.Ordinal)
            || !IsContinuousEffectLayerScopeValid(scope, layer))
        {
            return;
        }

        if (string.Equals(scope, "OBJECT", StringComparison.Ordinal))
        {
            if (!string.Equals(duration, "WHILE_SOURCE_ON_PUBLIC_FIELD", StringComparison.Ordinal))
            {
                return;
            }

            ValidateContinuousEffectStaticAuraMetadataValue(
                effectLabel,
                effectKind,
                "FRIENDLY_FIELD_EQUIPMENT_COUNT_TO_SOURCE_UNIT_POWER",
                "object static aura effect kind",
                errors);
            ValidateContinuousEffectStaticAuraMetadataValue(
                effectLabel,
                sourcePath,
                "CoreRuleEngine.ApplyFriendlyEquipmentStaticPowerRecompute",
                "object static aura source path",
                errors);
            ValidateContinuousEffectStaticAuraMetadataValue(
                effectLabel,
                condition,
                "SOURCE_PUBLIC_FIELD_UNIT_AND_FRIENDLY_PUBLIC_FIELD_EQUIPMENT_COUNT",
                "object static aura condition",
                errors);
            ValidateContinuousEffectStaticAuraMetadataValue(
                effectLabel,
                lifecycle,
                "RECOMPUTED_FROM_CURRENT_AUTHORITATIVE_FIELD_STATE",
                "object static aura lifecycle",
                errors);
            return;
        }

        if (string.Equals(scope, "BATTLEFIELD", StringComparison.Ordinal))
        {
            if (!string.Equals(duration, "WHILE_SOURCE_BATTLEFIELD_AND_PARTICIPANT_AT_BATTLEFIELD", StringComparison.Ordinal))
            {
                return;
            }

            ValidateContinuousEffectStaticAuraMetadataValue(
                effectLabel,
                effectKind,
                "BATTLEFIELD_ALL_UNITS_POWER_PLUS_ONE",
                "battlefield static aura effect kind",
                errors);
            ValidateContinuousEffectStaticAuraMetadataValue(
                effectLabel,
                sourceCardNo,
                ContinuousEffectStaticAuraCards.BattlefieldAllUnitsPowerPlusOneCardNo,
                "battlefield static aura source card no",
                errors);
            ValidateContinuousEffectStaticAuraMetadataValue(
                effectLabel,
                sourcePath,
                "CoreRuleEngine.ResolveBattlefieldAllUnitsPowerBonus",
                "battlefield static aura source path",
                errors);
            ValidateContinuousEffectStaticAuraMetadataValue(
                effectLabel,
                condition,
                "SOURCE_BATTLEFIELD_ALL_UNITS_POWER_PLUS_ONE_AND_PARTICIPANT_UNIT_AT_BATTLEFIELD",
                "battlefield static aura condition",
                errors);
            ValidateContinuousEffectStaticAuraMetadataValue(
                effectLabel,
                lifecycle,
                "DERIVED_FROM_CURRENT_BATTLEFIELD_OBJECT_LOCATIONS",
                "battlefield static aura lifecycle",
                errors);
        }
    }

    private static void ValidateContinuousEffectStaticAuraMetadataValue(
        string effectLabel,
        string? actual,
        string expected,
        string diagnosticLabel,
        List<string> errors)
    {
        if (actual is null || string.Equals(actual, expected, StringComparison.Ordinal))
        {
            return;
        }

        errors.Add($"{effectLabel} {diagnosticLabel} must be {expected}");
    }

    private static void ValidateContinuousEffectNonStaticAuraParticipantListAbsence(
        object? effectPayload,
        string effectLabel,
        string? layer,
        List<string> errors)
    {
        if (layer is null
            || !IsKnownContinuousEffectLayer(layer)
            || string.Equals(layer, ContinuousEffectLayers.StaticAura, StringComparison.Ordinal))
        {
            return;
        }

        ValidateContinuousEffectReadableStringListAbsence(
            effectPayload,
            "participantObjectIds",
            $"{effectLabel} {layer} participant object id list must be absent",
            errors);
        ValidateContinuousEffectReadableStringListAbsence(
            effectPayload,
            "participantDependencyObjectIds",
            $"{effectLabel} {layer} participant dependency object id list must be absent",
            errors);
    }

    private static void ValidateContinuousEffectNonStaticAuraDependencyListAbsence(
        object? effectPayload,
        string effectLabel,
        string? layer,
        List<string> errors)
    {
        if (layer is null
            || !IsKnownContinuousEffectLayer(layer)
            || string.Equals(layer, ContinuousEffectLayers.StaticAura, StringComparison.Ordinal))
        {
            return;
        }

        ValidateContinuousEffectReadableStringListAbsence(
            effectPayload,
            "sourceDependencyObjectIds",
            $"{effectLabel} {layer} source dependency object id list must be absent",
            errors);
        ValidateContinuousEffectReadableStringListAbsence(
            effectPayload,
            "targetDependencyObjectIds",
            $"{effectLabel} {layer} target dependency object id list must be absent",
            errors);
    }

    private static void ValidateContinuousEffectNonStaticAuraStaticMetadataAbsence(
        object? effectPayload,
        string effectLabel,
        string? layer,
        List<string> errors)
    {
        if (layer is null
            || !IsKnownContinuousEffectLayer(layer)
            || string.Equals(layer, ContinuousEffectLayers.StaticAura, StringComparison.Ordinal))
        {
            return;
        }

        ValidateContinuousEffectReadableStringAbsence(
            effectPayload,
            "condition",
            $"{effectLabel} {layer} condition must be absent",
            errors);
        ValidateContinuousEffectReadableStringAbsence(
            effectPayload,
            "lifecycle",
            $"{effectLabel} {layer} lifecycle must be absent",
            errors);
    }

    private static void ValidateContinuousEffectReadableStringListAbsence(
        object? effectPayload,
        string key,
        string diagnostic,
        List<string> errors)
    {
        if (!TryReadObjectStringList(effectPayload, key, out var values)
            || values.Count == 0)
        {
            return;
        }

        errors.Add(diagnostic);
    }

    private static void ValidateContinuousEffectReadableStringAbsence(
        object? effectPayload,
        string key,
        string diagnostic,
        List<string> errors)
    {
        if (!TryReadObjectString(effectPayload, key, out var value)
            || string.IsNullOrWhiteSpace(value))
        {
            return;
        }

        errors.Add(diagnostic);
    }

    private static void ValidateContinuousEffectStaticAuraDependencyListConsistency(
        object? effectPayload,
        string effectLabel,
        List<string> errors)
    {
        if (!TryReadObjectString(effectPayload, "layer", out var layer)
            || !string.Equals(layer, ContinuousEffectLayers.StaticAura, StringComparison.Ordinal))
        {
            return;
        }

        ValidateContinuousEffectStaticAuraRequiredListPresence(
            effectPayload,
            "sourceDependencyObjectIds",
            $"{effectLabel} static aura source dependency object id list is required",
            errors);
        ValidateContinuousEffectStaticAuraRequiredListPresence(
            effectPayload,
            "targetDependencyObjectIds",
            $"{effectLabel} static aura target dependency object id list is required",
            errors);
        ValidateContinuousEffectStaticAuraParticipantObjectListPresence(
            effectPayload,
            effectLabel,
            errors);
        ValidateContinuousEffectStaticAuraParticipantDependencyListPresence(
            effectPayload,
            effectLabel,
            errors);
        ValidateContinuousEffectStaticAuraRequiredSourceOrderPresence(
            effectPayload,
            $"{effectLabel} static aura source order is required",
            errors);
        ValidateContinuousEffectStaticAuraReadableIntAbsence(
            effectPayload,
            "requestedPowerDelta",
            $"{effectLabel} static aura requested power delta must be absent",
            errors);
        ValidateContinuousEffectStaticAuraReadableIntAbsence(
            effectPayload,
            "appliedPowerDelta",
            $"{effectLabel} static aura applied power delta must be absent",
            errors);
        ValidateContinuousEffectStaticAuraReadableIntAbsence(
            effectPayload,
            "minimumPower",
            $"{effectLabel} static aura minimum power must be absent",
            errors);
        ValidateContinuousEffectStaticAuraReadableIntAbsence(
            effectPayload,
            "resultingPower",
            $"{effectLabel} static aura resulting power must be absent",
            errors);
        ValidateContinuousEffectStaticAuraReadableIntAbsence(
            effectPayload,
            "appliedOrder",
            $"{effectLabel} static aura applied order must be absent",
            errors);
        ValidateContinuousEffectStaticAuraDependencyListMembership(
            effectPayload,
            "sourceObjectId",
            "sourceDependencyObjectIds",
            $"{effectLabel} static aura source dependency object id list must include source object id",
            errors);
        ValidateContinuousEffectStaticAuraDependencyListMembership(
            effectPayload,
            "targetObjectId",
            "targetDependencyObjectIds",
            $"{effectLabel} static aura target dependency object id list must include target object id",
            errors);
        ValidateContinuousEffectStaticAuraParticipantDependencyListMembership(
            effectPayload,
            effectLabel,
            errors);
        ValidateContinuousEffectStaticAuraBattlefieldParticipantObjectListConsistency(
            effectPayload,
            effectLabel,
            errors);
    }

    private static void ValidateContinuousEffectStaticAuraRequiredListPresence(
        object? effectPayload,
        string key,
        string diagnostic,
        List<string> errors)
    {
        if (!TryReadObjectValue(effectPayload, key, out var listPayload)
            || IsNullSnapshotPayloadValue(listPayload))
        {
            errors.Add(diagnostic);
        }
    }

    private static void ValidateContinuousEffectStaticAuraRequiredSourceOrderPresence(
        object? effectPayload,
        string diagnostic,
        List<string> errors)
    {
        if (!TryReadObjectValue(effectPayload, "sourceOrder", out var sourceOrderPayload)
            || IsNullSnapshotPayloadValue(sourceOrderPayload))
        {
            errors.Add(diagnostic);
        }
    }

    private static void ValidateContinuousEffectStaticAuraReadableIntAbsence(
        object? effectPayload,
        string key,
        string diagnostic,
        List<string> errors)
    {
        if (!TryReadObjectValue(effectPayload, key, out var valuePayload)
            || IsNullSnapshotPayloadValue(valuePayload)
            || !TryReadIntValue(valuePayload, out _))
        {
            return;
        }

        errors.Add(diagnostic);
    }

    private static void ValidateContinuousEffectStaticAuraDependencyListMembership(
        object? effectPayload,
        string objectIdKey,
        string dependencyListKey,
        string diagnosticPrefix,
        List<string> errors)
    {
        if (!TryReadObjectString(effectPayload, objectIdKey, out var objectId)
            || !TryReadObjectStringList(effectPayload, dependencyListKey, out var dependencyObjectIds)
            || dependencyObjectIds.Count == 0
            || dependencyObjectIds.Contains(objectId, StringComparer.Ordinal))
        {
            return;
        }

        errors.Add($"{diagnosticPrefix} {objectId}");
    }

    private static void ValidateContinuousEffectStaticAuraParticipantObjectListPresence(
        object? effectPayload,
        string effectLabel,
        List<string> errors)
    {
        if (!TryReadObjectStringList(effectPayload, "participantDependencyObjectIds", out var participantDependencyObjectIds)
            || participantDependencyObjectIds.Count == 0)
        {
            return;
        }

        if (!TryReadObjectValue(effectPayload, "participantObjectIds", out var participantObjectIdsPayload)
            || IsNullSnapshotPayloadValue(participantObjectIdsPayload))
        {
            errors.Add(
                $"{effectLabel} static aura participant object id list is required when participant dependency object id list is present");
        }
    }

    private static void ValidateContinuousEffectStaticAuraParticipantDependencyListPresence(
        object? effectPayload,
        string effectLabel,
        List<string> errors)
    {
        if (!TryReadObjectStringList(effectPayload, "participantObjectIds", out var participantObjectIds)
            || participantObjectIds.Count == 0)
        {
            return;
        }

        if (!TryReadObjectValue(effectPayload, "participantDependencyObjectIds", out var participantDependencyObjectIdsPayload)
            || IsNullSnapshotPayloadValue(participantDependencyObjectIdsPayload))
        {
            errors.Add(
                $"{effectLabel} static aura participant dependency object id list is required when participant object id list is present");
        }
    }

    private static void ValidateContinuousEffectStaticAuraParticipantDependencyListMembership(
        object? effectPayload,
        string effectLabel,
        List<string> errors)
    {
        if (!TryReadObjectStringList(effectPayload, "participantObjectIds", out var participantObjectIds)
            || participantObjectIds.Count == 0
            || !TryReadObjectStringList(effectPayload, "participantDependencyObjectIds", out var participantDependencyObjectIds)
            || participantDependencyObjectIds.Count == 0)
        {
            return;
        }

        foreach (var participantObjectId in participantObjectIds.Distinct(StringComparer.Ordinal))
        {
            if (participantDependencyObjectIds.Contains(participantObjectId, StringComparer.Ordinal))
            {
                continue;
            }

            errors.Add(
                $"{effectLabel} static aura participant dependency object id list must include participant object id {participantObjectId}");
        }
    }

    private static void ValidateContinuousEffectStaticAuraBattlefieldParticipantObjectListConsistency(
        object? effectPayload,
        string effectLabel,
        List<string> errors)
    {
        if (!TryReadObjectString(effectPayload, "scope", out var scope)
            || !string.Equals(scope, "BATTLEFIELD", StringComparison.Ordinal)
            || !TryReadObjectString(effectPayload, "duration", out var duration)
            || !string.Equals(
                duration,
                "WHILE_SOURCE_BATTLEFIELD_AND_PARTICIPANT_AT_BATTLEFIELD",
                StringComparison.Ordinal))
        {
            return;
        }

        if (!TryReadObjectValue(effectPayload, "participantObjectIds", out var participantObjectIdsPayload)
            || IsNullSnapshotPayloadValue(participantObjectIdsPayload))
        {
            errors.Add($"{effectLabel} battlefield static aura participant object id list is required");
            return;
        }

        if (!TryReadObjectString(effectPayload, "targetObjectId", out var targetObjectId)
            || !TryReadObjectStringList(effectPayload, "participantObjectIds", out var participantObjectIds)
            || participantObjectIds.Count == 0
            || participantObjectIds.Contains(targetObjectId, StringComparer.Ordinal))
        {
