            || !IsKnownContinuousEffectLayer(layer)
            || !string.Equals(layer, ContinuousEffectLayers.PowerModifier, StringComparison.Ordinal)
            || !IsContinuousEffectLayerScopeValid(scope, layer)
            || !string.Equals(layerEngineStatus, "FOUNDATION_ONLY", StringComparison.Ordinal)
            || !TryReadObjectStringList(effectPayload, "deferredLayerEngineResiduals", out var residuals)
            || residuals.Count == 0)
        {
            return;
        }

        if (StringListsEqual(residuals, ContinuousEffectFoundationResiduals()))
        {
            return;
        }

        errors.Add(
            $"{effectLabel} POWER_MODIFIER foundation deferred LayerEngine residual list must match current foundation residual set");
    }

    private static void ValidateContinuousEffectStaticAuraFoundationResidualCanonicality(
        object? effectPayload,
        string effectLabel,
        string? scope,
        string? layer,
        string? layerEngineStatus,
        List<string> errors)
    {
        if (scope is null
            || layer is null
            || !IsKnownContinuousEffectScope(scope)
            || !IsKnownContinuousEffectLayer(layer)
            || !string.Equals(layer, ContinuousEffectLayers.StaticAura, StringComparison.Ordinal)
            || !IsContinuousEffectLayerScopeValid(scope, layer)
            || !string.Equals(layerEngineStatus, "FOUNDATION_ONLY", StringComparison.Ordinal)
            || !TryReadObjectStringList(effectPayload, "deferredLayerEngineResiduals", out var residuals)
            || residuals.Count == 0)
        {
            return;
        }

        if (StringListsEqual(residuals, ContinuousEffectFoundationResiduals()))
        {
            return;
        }

        errors.Add(
            $"{effectLabel} static aura deferred LayerEngine residual list must match current foundation residual set");
    }

    private static IReadOnlyList<string> ContinuousEffectFoundationResiduals()
    {
        return
        [
            "timestamp ordering",
            "dependency ordering",
            "source ordering",
            "keyword gain/loss layering",
            "multiple equipment/static aura interactions",
            "minimum-power layering",
            "full official LayerEngine coverage"
        ];
    }

    private static void ValidateContinuousEffectLayerEngineResidualConsistency(
        object? effectPayload,
        string effectLabel,
        string? layer,
        string? layerEngineStatus,
        List<string> errors)
    {
        var hasFoundationOnlyStatus = string.Equals(layerEngineStatus, "FOUNDATION_ONLY", StringComparison.Ordinal);
        var isStaticAuraLayer = string.Equals(layer, ContinuousEffectLayers.StaticAura, StringComparison.Ordinal);
        if (!TryReadObjectValue(effectPayload, "deferredLayerEngineResiduals", out var residualPayload)
            || IsNullSnapshotPayloadValue(residualPayload))
        {
            if (hasFoundationOnlyStatus || isStaticAuraLayer)
            {
                errors.Add($"{effectLabel} deferred LayerEngine residual list is required");
            }

            if (isStaticAuraLayer && !hasFoundationOnlyStatus)
            {
                errors.Add($"{effectLabel} static aura requires foundation-only layer engine status");
            }

            return;
        }

        if (!TryReadStringListValue(residualPayload, out var residuals))
        {
            if (isStaticAuraLayer && !hasFoundationOnlyStatus)
            {
                errors.Add($"{effectLabel} static aura requires foundation-only layer engine status");
            }

            return;
        }

        if (residuals.Count == 0)
        {
            errors.Add($"{effectLabel} deferred LayerEngine residual list is required");
        }

        if (!hasFoundationOnlyStatus)
        {
            errors.Add($"{effectLabel} deferred LayerEngine residuals require foundation-only layer engine status");
            if (isStaticAuraLayer)
            {
                errors.Add($"{effectLabel} static aura requires foundation-only layer engine status");
            }
        }
    }

    private static void ValidateSpectatorTriggerQueuePayloads(
        IReadOnlyDictionary<string, object?> timing,
        MatchState authoritativeState,
        List<string> errors)
    {
        if (!timing.TryGetValue("triggerQueue", out var triggerQueuePayload)
            || IsNullSnapshotPayloadValue(triggerQueuePayload))
        {
            errors.Add("spectator replay frame timing trigger queue is required");
            if (authoritativeState.TriggerQueue.Count > 0)
            {
                AddSpectatorTriggerQueueCountMismatch(
                    spectatorCount: 0,
                    authoritativeCount: authoritativeState.TriggerQueue.Count,
                    errors);
            }

            ReportMissingSpectatorTriggerQueueAuthoritativeKeySet(authoritativeState.TriggerQueue, errors);
            return;
        }

        if (!TryReadObjectListValue(triggerQueuePayload, out var spectatorTriggers))
        {
            errors.Add("spectator replay frame timing trigger queue payload is required");
            if (authoritativeState.TriggerQueue.Count > 0)
            {
                AddSpectatorTriggerQueueCountMismatch(
                    spectatorCount: 0,
                    authoritativeCount: authoritativeState.TriggerQueue.Count,
                    errors);
            }

            ReportMissingSpectatorTriggerQueueAuthoritativeKeySet(authoritativeState.TriggerQueue, errors);
            return;
        }

        var authoritativeTriggers = authoritativeState.TriggerQueue;
        var validateAuthoritativeParity = spectatorTriggers.Count == authoritativeTriggers.Count;
        if (!validateAuthoritativeParity)
        {
            AddSpectatorTriggerQueueCountMismatch(
                spectatorTriggers.Count,
                authoritativeTriggers.Count,
                errors);
        }

        var seatPlayerIds = BuildNormalizedPlayerIdSet(authoritativeState.Seats.Keys);
        var knownObjectIds = BuildAuthoritativeStateKnownObjectIds(authoritativeState);
        var objectCardNos = BuildAuthoritativeStateObjectCardNoIndex(authoritativeState);
        var objectPowers = BuildAuthoritativeStateObjectPowerIndex(authoritativeState);
        var objectControllers = BuildAuthoritativeStateObjectControllerIndex(authoritativeState);
        var objectFaceDowns = BuildAuthoritativeStateObjectFaceDownIndex(authoritativeState);
        var objectTags = BuildAuthoritativeStateObjectTagIndex(authoritativeState);
        var battlefieldStateObjectIds = BuildAuthoritativeStateBattlefieldStateObjectIds(authoritativeState);
        var playerBattlefieldObjectIdsByPlayer =
            BuildAuthoritativeStatePlayerBattlefieldObjectIdsByPlayer(authoritativeState.PlayerZones);
        var playerBaseObjectIdsByPlayer =
            BuildAuthoritativeStatePlayerBaseObjectIdsByPlayer(authoritativeState.PlayerZones);
        var playerGraveyardObjectIdsByPlayer =
            BuildAuthoritativeStatePlayerGraveyardObjectIdsByPlayer(authoritativeState.PlayerZones);
        var playerFieldObjectIdsByPlayer =
            BuildAuthoritativeStatePlayerFieldObjectIdsByPlayer(authoritativeState.PlayerZones);
        var seenTriggerIds = new HashSet<string>(StringComparer.Ordinal);
        foreach (var spectatorTrigger in spectatorTriggers)
        {
            if (!IsSnapshotPlayerPayloadObject(spectatorTrigger))
            {
                errors.Add("spectator replay frame timing trigger queue item payload is required");
                continue;
            }

            ValidateSnapshotPayloadObjectPropertyNames(
                spectatorTrigger,
                "spectator replay frame timing trigger queue item",
                errors);
            ValidateSpectatorTriggerQueuePayloadValues(
                spectatorTrigger,
                seenTriggerIds,
                seatPlayerIds,
                knownObjectIds,
                objectCardNos,
                objectPowers,
                objectControllers,
                objectFaceDowns,
                objectTags,
                authoritativeState.ObjectLocations,
                playerBattlefieldObjectIdsByPlayer,
                playerBaseObjectIdsByPlayer,
                playerGraveyardObjectIdsByPlayer,
                playerFieldObjectIdsByPlayer,
                battlefieldStateObjectIds,
                authoritativeState.Tick,
                authoritativeState.TurnNumber,
                errors);
        }

        var authoritativeTriggersById = BuildAuthoritativeTriggerQueueById(authoritativeTriggers);

        ValidateSpectatorTriggerQueueAuthoritativeKeySet(
            spectatorTriggers,
            authoritativeTriggersById,
            errors);
        ValidateSpectatorTriggerQueueKeyedAuthoritativeValues(
            spectatorTriggers,
            authoritativeTriggersById,
            authoritativeState,
            errors);

        if (!validateAuthoritativeParity)
        {
            return;
        }

        var triggerIdsMatch = true;
        var controllerIdsMatch = true;
        var sourceObjectIdsMatch = true;
        var sourceVisibilitiesMatch = true;
        var effectKindsMatch = true;
        var triggeredEventKindsMatch = true;

        for (var index = 0; index < authoritativeTriggers.Count; index++)
        {
            var spectatorTrigger = spectatorTriggers[index];
            if (!IsSnapshotPlayerPayloadObject(spectatorTrigger))
            {
                continue;
            }

            var authoritativeTrigger = authoritativeTriggers[index];
            var hiddenSource = IsHiddenBattlefieldStandbyForSpectator(
                authoritativeState,
                authoritativeTrigger.SourceObjectId);
            var expectedSourceObjectId = hiddenSource ? "HIDDEN" : authoritativeTrigger.SourceObjectId;
            var expectedSourceVisibility = hiddenSource ? "HIDDEN" : "VISIBLE";
            var expectedEffectKind = hiddenSource ? "HIDDEN" : authoritativeTrigger.EffectKind;

            if (!TryReadObjectString(spectatorTrigger, "triggerId", out var triggerId)
                || !string.Equals(triggerId, authoritativeTrigger.TriggerId, StringComparison.Ordinal))
            {
                triggerIdsMatch = false;
            }

            if (!TryReadObjectString(spectatorTrigger, "controllerId", out var controllerId)
                || !string.Equals(controllerId, authoritativeTrigger.ControllerId, StringComparison.Ordinal))
            {
                controllerIdsMatch = false;
            }

            if (!TryReadObjectString(spectatorTrigger, "sourceObjectId", out var sourceObjectId)
                || !string.Equals(sourceObjectId, expectedSourceObjectId, StringComparison.Ordinal))
            {
                sourceObjectIdsMatch = false;
            }

            if (!TryReadObjectString(spectatorTrigger, "sourceVisibility", out var sourceVisibility)
                || !string.Equals(sourceVisibility, expectedSourceVisibility, StringComparison.Ordinal))
            {
                sourceVisibilitiesMatch = false;
            }

            if (!TryReadObjectString(spectatorTrigger, "effectKind", out var effectKind)
                || !string.Equals(effectKind, expectedEffectKind, StringComparison.Ordinal))
            {
                effectKindsMatch = false;
            }

            if (!TryReadObjectString(spectatorTrigger, "triggeredByEventKind", out var triggeredEventKind)
                || !string.Equals(triggeredEventKind, authoritativeTrigger.TriggeredByEventKind, StringComparison.Ordinal))
            {
                triggeredEventKindsMatch = false;
            }
        }

        if (!triggerIdsMatch)
        {
            errors.Add("spectator replay frame timing trigger queue ids disagree with authoritative state trigger queue ids");
        }

        if (!controllerIdsMatch)
        {
            errors.Add("spectator replay frame timing trigger queue controller ids disagree with authoritative state trigger queue controller ids");
        }

        if (!sourceObjectIdsMatch)
        {
            errors.Add("spectator replay frame timing trigger queue source object ids disagree with authoritative state trigger queue source object ids");
        }

        if (!sourceVisibilitiesMatch)
        {
            errors.Add("spectator replay frame timing trigger queue source visibilities disagree with authoritative state trigger queue source visibilities");
        }

        if (!effectKindsMatch)
        {
            errors.Add("spectator replay frame timing trigger queue effect kinds disagree with authoritative state trigger queue effect kinds");
        }

        if (!triggeredEventKindsMatch)
        {
            errors.Add("spectator replay frame timing trigger queue triggered event kinds disagree with authoritative state trigger queue triggered event kinds");
        }
    }

    private static IReadOnlyDictionary<string, TriggerQueueItemState> BuildAuthoritativeTriggerQueueById(
        IReadOnlyList<TriggerQueueItemState> authoritativeTriggers)
    {
        var authoritativeTriggersById = new Dictionary<string, TriggerQueueItemState>(StringComparer.Ordinal);
        foreach (var authoritativeTrigger in authoritativeTriggers)
        {
            if (string.IsNullOrWhiteSpace(authoritativeTrigger.TriggerId))
            {
                continue;
            }

            var normalizedTriggerId = authoritativeTrigger.TriggerId.Trim();
            if (!authoritativeTriggersById.ContainsKey(normalizedTriggerId))
            {
                authoritativeTriggersById.Add(normalizedTriggerId, authoritativeTrigger);
            }
        }

        return authoritativeTriggersById;
    }

    private static void ReportMissingSpectatorTriggerQueueAuthoritativeKeySet(
        IReadOnlyList<TriggerQueueItemState> authoritativeTriggers,
        List<string> errors)
    {
        ValidateSpectatorTriggerQueueAuthoritativeKeySet(
            Array.Empty<object?>(),
            BuildAuthoritativeTriggerQueueById(authoritativeTriggers),
            errors);
    }

    private static void ValidateSpectatorTriggerQueueAuthoritativeKeySet(
        IReadOnlyList<object?> triggerPayloads,
        IReadOnlyDictionary<string, TriggerQueueItemState> authoritativeTriggersById,
        List<string> errors)
    {
        const string payloadLabel = "spectator replay frame timing trigger queue item";
        var actualTriggerIds = new HashSet<string>(StringComparer.Ordinal);
        foreach (var triggerPayload in triggerPayloads)
        {
            if (!IsSnapshotPlayerPayloadObject(triggerPayload)
                || !TryReadObjectString(triggerPayload, "triggerId", out var triggerId)
                || string.IsNullOrWhiteSpace(triggerId))
            {
                continue;
            }

            var normalizedTriggerId = triggerId.Trim();
            actualTriggerIds.Add(normalizedTriggerId);
            if (!authoritativeTriggersById.ContainsKey(normalizedTriggerId))
            {
                errors.Add(
                    $"{payloadLabel} trigger id {normalizedTriggerId} is not present in authoritative state trigger queue");
            }
        }

        foreach (var authoritativeTriggerId in authoritativeTriggersById.Keys.OrderBy(id => id, StringComparer.Ordinal))
        {
            if (!actualTriggerIds.Contains(authoritativeTriggerId))
            {
                errors.Add(
                    $"{payloadLabel} trigger id {authoritativeTriggerId} is required by authoritative state trigger queue");
            }
        }
    }

    private static void ValidateSpectatorTriggerQueueKeyedAuthoritativeValues(
        IReadOnlyList<object?> triggerPayloads,
        IReadOnlyDictionary<string, TriggerQueueItemState> authoritativeTriggersById,
        MatchState authoritativeState,
        List<string> errors)
    {
        foreach (var triggerPayload in triggerPayloads)
        {
            if (!IsSnapshotPlayerPayloadObject(triggerPayload)
                || !TryReadObjectString(triggerPayload, "triggerId", out var triggerId)
                || string.IsNullOrWhiteSpace(triggerId))
            {
                continue;
            }

            var normalizedTriggerId = triggerId.Trim();
            if (!authoritativeTriggersById.TryGetValue(normalizedTriggerId, out var authoritativeTrigger))
            {
                continue;
            }

            var hiddenSource = IsHiddenBattlefieldStandbyForSpectator(
                authoritativeState,
                authoritativeTrigger.SourceObjectId);
            var expectedSourceObjectId = hiddenSource ? "HIDDEN" : authoritativeTrigger.SourceObjectId;
            var expectedSourceVisibility = hiddenSource ? "HIDDEN" : "VISIBLE";
            var expectedEffectKind = hiddenSource ? "HIDDEN" : authoritativeTrigger.EffectKind;

            ValidateSpectatorTriggerQueueKeyedRequiredStringValue(
                triggerPayload,
                "controllerId",
                "controller id",
                authoritativeTrigger.ControllerId,
                normalizedTriggerId,
                errors);
            ValidateSpectatorTriggerQueueKeyedRequiredStringValue(
                triggerPayload,
                "sourceObjectId",
                "source object id",
                expectedSourceObjectId,
                normalizedTriggerId,
                errors);
            ValidateSpectatorTriggerQueueKeyedRequiredStringValue(
                triggerPayload,
                "sourceVisibility",
                "source visibility",
                expectedSourceVisibility,
                normalizedTriggerId,
                errors);
            ValidateSpectatorTriggerQueueKeyedRequiredStringValue(
                triggerPayload,
                "effectKind",
                "effect kind",
                expectedEffectKind,
                normalizedTriggerId,
                errors);
            ValidateSpectatorTriggerQueueKeyedRequiredStringValue(
                triggerPayload,
                "triggeredByEventKind",
                "triggered event kind",
                authoritativeTrigger.TriggeredByEventKind,
                normalizedTriggerId,
                errors);
        }
    }

    private static void ValidateSpectatorTriggerQueueKeyedRequiredStringValue(
        object? triggerPayload,
        string key,
        string fieldLabel,
        string expected,
        string triggerId,
        List<string> errors)
    {
        if (!TryReadObjectString(triggerPayload, key, out var actual))
        {
            var detail = FormatExpectedActualForRecovery(
                expected,
                FormatUnreadableObjectValue(triggerPayload, key));
            errors.Add(
                $"spectator replay frame timing trigger queue item {fieldLabel} does not match authoritative state trigger queue {fieldLabel} {expected} for trigger id {triggerId}; {detail}");
            return;
        }

        if (!string.Equals(actual, expected, StringComparison.Ordinal))
        {
            var detail = FormatExpectedActualForRecovery(expected, actual);
            errors.Add(
                $"spectator replay frame timing trigger queue item {fieldLabel} {actual} does not match authoritative state trigger queue {fieldLabel} {expected} for trigger id {triggerId}; {detail}");
        }
    }

    private static void AddSpectatorTriggerQueueCountMismatch(
        int spectatorCount,
        int authoritativeCount,
        List<string> errors)
    {
        errors.Add(
            $"spectator replay frame timing trigger queue count {spectatorCount} does not match authoritative state trigger queue count {authoritativeCount}; {FormatExpectedActualForRecovery(authoritativeCount, spectatorCount)}");
    }

