    private static void ValidateTriggerQueueStandardLastBreathSourceObjectIdContext(
        string payloadLabel,
        string? triggerId,
        string? controllerId,
        string? sourceObjectId,
        string? effectKind,
        IReadOnlyDictionary<string, string>? objectControllers,
        string objectControllerLabel,
        IReadOnlyDictionary<string, string?>? objectCardNos,
        string objectCardNoLabel,
        IReadOnlyDictionary<string, int>? objectPowers,
        string objectPowerLabel,
        IReadOnlyDictionary<string, bool>? objectFaceDowns,
        string objectFaceDownLabel,
        IReadOnlyDictionary<string, IReadOnlySet<string>>? objectTags,
        string objectTagLabel,
        IReadOnlyDictionary<string, ObjectLocationState>? objectLocations,
        string objectLocationLabel,
        IReadOnlyDictionary<string, IReadOnlySet<string>>? playerBaseObjectIdsByPlayer,
        string playerBaseObjectIdsLabel,
        IReadOnlyDictionary<string, IReadOnlySet<string>>? playerGraveyardObjectIdsByPlayer,
        string playerGraveyardObjectIdsLabel,
        string expectedEffectKind,
        string diagnosticName,
        List<string> errors)
    {
        if (triggerId is null
            || !IsStandardLastBreathTriggerForRecovery(triggerId, effectKind, expectedEffectKind)
            || !IsStandardLastBreathTriggerIdForRecovery(triggerId, expectedEffectKind)
            || string.IsNullOrWhiteSpace(sourceObjectId)
            || string.Equals(sourceObjectId, "HIDDEN", StringComparison.Ordinal))
        {
            return;
        }

        var sourceObjectSuffix = $"-{sourceObjectId}-{expectedEffectKind}";
        if (!triggerId.EndsWith(sourceObjectSuffix, StringComparison.Ordinal))
        {
            errors.Add(
                $"{payloadLabel} {diagnosticName} source object id {sourceObjectId} must match trigger id source object id before {expectedEffectKind}");
            return;
        }

        if (triggerId.Length - sourceObjectSuffix.Length <= StandardTriggerIdPrefixForRecovery.Length)
        {
            errors.Add(
                $"{payloadLabel} {diagnosticName} trigger id stack item id is required before source object id {sourceObjectId}");
        }

        if (objectLocations is not null
            && objectLocations.TryGetValue(sourceObjectId, out var sourceLocation)
            && !string.IsNullOrWhiteSpace(sourceLocation.Zone)
            && !string.Equals(sourceLocation.Zone.Trim(), "GRAVEYARD", StringComparison.Ordinal))
        {
            var sourceZone = sourceLocation.Zone.Trim();
            errors.Add(
                $"{payloadLabel} {diagnosticName} source object id {sourceObjectId} location zone {sourceZone} must be GRAVEYARD in {objectLocationLabel}");
        }

        if (objectLocations is not null
            && objectLocations.TryGetValue(sourceObjectId, out var sourceGraveyardLocation)
            && !string.IsNullOrWhiteSpace(sourceGraveyardLocation.Zone)
            && string.Equals(sourceGraveyardLocation.Zone.Trim(), "GRAVEYARD", StringComparison.Ordinal)
            && !string.IsNullOrWhiteSpace(sourceGraveyardLocation.PlayerId)
            && !string.IsNullOrWhiteSpace(controllerId)
            && !string.Equals(controllerId, "HIDDEN", StringComparison.Ordinal)
            && !string.Equals(sourceGraveyardLocation.PlayerId.Trim(), controllerId, StringComparison.Ordinal))
        {
            var sourceLocationPlayerId = sourceGraveyardLocation.PlayerId.Trim();
            errors.Add(
                $"{payloadLabel} {diagnosticName} source object id {sourceObjectId} location player id {sourceLocationPlayerId} must match trigger controller id {controllerId} in {objectLocationLabel}");
        }

        if (objectLocations is not null
            && objectLocations.TryGetValue(sourceObjectId, out sourceGraveyardLocation)
            && !string.IsNullOrWhiteSpace(sourceGraveyardLocation.Zone)
            && string.Equals(sourceGraveyardLocation.Zone.Trim(), "GRAVEYARD", StringComparison.Ordinal)
            && !string.IsNullOrWhiteSpace(sourceGraveyardLocation.PlayerId)
            && playerGraveyardObjectIdsByPlayer is not null
            && playerGraveyardObjectIdsByPlayer.TryGetValue(
                sourceGraveyardLocation.PlayerId.Trim(),
                out var graveyardObjectIds)
            && !graveyardObjectIds.Contains(sourceObjectId))
        {
            var sourceLocationPlayerId = sourceGraveyardLocation.PlayerId.Trim();
            errors.Add(
                $"{payloadLabel} {diagnosticName} source object id {sourceObjectId} location player id {sourceLocationPlayerId} must include source object in {playerGraveyardObjectIdsLabel} graveyard");
        }

        if (controllerId is not null
            && !string.Equals(controllerId, "HIDDEN", StringComparison.Ordinal)
            && objectControllers is not null
            && objectControllers.TryGetValue(sourceObjectId, out var sourceControllerId)
            && !string.Equals(sourceControllerId, controllerId, StringComparison.Ordinal))
        {
            errors.Add(
                $"{payloadLabel} {diagnosticName} source object id {sourceObjectId} controller id {sourceControllerId} must match trigger controller id {controllerId} in {objectControllerLabel}");
        }

        if (objectCardNos is not null
            && objectCardNos.TryGetValue(sourceObjectId, out var sourceCardNo))
        {
            var expectedSourceCardNos = GetStandardLastBreathSourceCardNosForRecovery(expectedEffectKind);
            if (expectedSourceCardNos.Length > 0
                && !Array.Exists(
                    expectedSourceCardNos,
                    expectedSourceCardNo => string.Equals(expectedSourceCardNo, sourceCardNo, StringComparison.Ordinal)))
            {
                var sourceCardNoLabel = sourceCardNo is null ? "<null>" : sourceCardNo;
                errors.Add(
                    $"{payloadLabel} {diagnosticName} source object id {sourceObjectId} card no {sourceCardNoLabel} must be {FormatExpectedCardNosForRecovery(expectedSourceCardNos)} in {objectCardNoLabel}");
            }
        }

        if (string.Equals(expectedEffectKind, UnsungHeroLastBreathPowerfulDrawEffectKindForRecovery, StringComparison.Ordinal)
            && objectPowers is not null
            && objectPowers.TryGetValue(sourceObjectId, out var sourcePower)
            && sourcePower < PowerfulUnitPowerThresholdForRecovery)
        {
            errors.Add(
                $"{payloadLabel} {diagnosticName} source object id {sourceObjectId} power {sourcePower} must be at least {PowerfulUnitPowerThresholdForRecovery} in {objectPowerLabel}");
        }

        var hasKnownPoroBaseAllyContext = false;
        var hasOtherFriendlyFaceUpBaseUnit = false;
        if (string.Equals(expectedEffectKind, SadPoroLastBreathDrawEffectKindForRecovery, StringComparison.Ordinal)
            || string.Equals(expectedEffectKind, LoyalPoroLastBreathDrawEffectKindForRecovery, StringComparison.Ordinal))
        {
            hasKnownPoroBaseAllyContext = TryHasOtherFriendlyFaceUpBaseUnitForStandardLastBreathForRecovery(
                controllerId,
                sourceObjectId,
                playerBaseObjectIdsByPlayer,
                objectControllers,
                objectFaceDowns,
                objectTags,
                out hasOtherFriendlyFaceUpBaseUnit);
        }

        if (string.Equals(expectedEffectKind, SadPoroLastBreathDrawEffectKindForRecovery, StringComparison.Ordinal)
            && hasKnownPoroBaseAllyContext
            && hasOtherFriendlyFaceUpBaseUnit)
        {
            errors.Add(
                $"{payloadLabel} {diagnosticName} source object id {sourceObjectId} must be isolated from other friendly face-up units in {playerBaseObjectIdsLabel} base for controller id {controllerId}");
        }

        if (string.Equals(expectedEffectKind, LoyalPoroLastBreathDrawEffectKindForRecovery, StringComparison.Ordinal)
            && hasKnownPoroBaseAllyContext
            && !hasOtherFriendlyFaceUpBaseUnit)
        {
            errors.Add(
                $"{payloadLabel} {diagnosticName} source object id {sourceObjectId} requires another friendly face-up unit in {playerBaseObjectIdsLabel} base for controller id {controllerId}");
        }

        if (objectTags is not null
            && objectTags.TryGetValue(sourceObjectId, out var sourceTags)
            && sourceTags.Contains(CardObjectTags.EquipmentCard)
            && !sourceTags.Contains(CardObjectTags.UnitCard))
        {
            errors.Add(
                $"{payloadLabel} {diagnosticName} source object id {sourceObjectId} must not be an equipment card in {objectTagLabel}");
        }

        if (!IsWatchfulSentinelLastBreathDrawEffectForRecovery(expectedEffectKind)
            && objectTags is not null
            && objectTags.TryGetValue(sourceObjectId, out var unitSourceTags)
            && !unitSourceTags.Contains(CardObjectTags.UnitCard))
        {
            errors.Add(
                $"{payloadLabel} {diagnosticName} source object id {sourceObjectId} must be a unit card in {objectTagLabel}");
        }

        if (!IsWatchfulSentinelLastBreathDrawEffectForRecovery(expectedEffectKind)
            && objectFaceDowns is not null
            && objectFaceDowns.TryGetValue(sourceObjectId, out var isFaceDown)
            && isFaceDown)
        {
            errors.Add(
                $"{payloadLabel} {diagnosticName} source object id {sourceObjectId} must not be face down in {objectFaceDownLabel}");
        }

        if (!IsWatchfulSentinelLastBreathDrawEffectForRecovery(expectedEffectKind)
            && objectTags is not null
            && objectTags.TryGetValue(sourceObjectId, out var standbySourceTags)
            && standbySourceTags.Contains(CardObjectTags.Standby))
        {
            errors.Add(
                $"{payloadLabel} {diagnosticName} source object id {sourceObjectId} must not be a standby card in {objectTagLabel}");
        }
    }

    private static bool TryHasOtherFriendlyFaceUpBaseUnitForStandardLastBreathForRecovery(
        string? controllerId,
        string sourceObjectId,
        IReadOnlyDictionary<string, IReadOnlySet<string>>? playerBaseObjectIdsByPlayer,
        IReadOnlyDictionary<string, string>? objectControllers,
        IReadOnlyDictionary<string, bool>? objectFaceDowns,
        IReadOnlyDictionary<string, IReadOnlySet<string>>? objectTags,
        out bool hasOtherFriendlyFaceUpBaseUnit)
    {
        hasOtherFriendlyFaceUpBaseUnit = false;

        if (string.IsNullOrWhiteSpace(controllerId)
            || string.Equals(controllerId, "HIDDEN", StringComparison.Ordinal)
            || playerBaseObjectIdsByPlayer is null
            || objectTags is null)
        {
            return false;
        }

        if (!playerBaseObjectIdsByPlayer.TryGetValue(controllerId, out var baseObjectIds))
        {
            return true;
        }

        hasOtherFriendlyFaceUpBaseUnit = baseObjectIds.Any(candidateObjectId =>
            IsOtherFriendlyFaceUpBaseUnitForStandardLastBreathForRecovery(
                candidateObjectId,
                controllerId,
                sourceObjectId,
                objectControllers,
                objectFaceDowns,
                objectTags));
        return true;
    }

    private static bool IsOtherFriendlyFaceUpBaseUnitForStandardLastBreathForRecovery(
        string candidateObjectId,
        string controllerId,
        string sourceObjectId,
        IReadOnlyDictionary<string, string>? objectControllers,
        IReadOnlyDictionary<string, bool>? objectFaceDowns,
        IReadOnlyDictionary<string, IReadOnlySet<string>> objectTags)
    {
        if (string.IsNullOrWhiteSpace(candidateObjectId)
            || string.Equals(candidateObjectId, sourceObjectId, StringComparison.Ordinal))
        {
            return false;
        }

        if (objectControllers is not null
            && objectControllers.TryGetValue(candidateObjectId, out var candidateControllerId)
            && !string.Equals(candidateControllerId, controllerId, StringComparison.Ordinal))
        {
            return false;
        }

        if (objectFaceDowns is not null
            && objectFaceDowns.TryGetValue(candidateObjectId, out var isFaceDown)
            && isFaceDown)
        {
            return false;
        }

        return objectTags.TryGetValue(candidateObjectId, out var candidateTags)
            && candidateTags.Contains(CardObjectTags.UnitCard)
            && !candidateTags.Contains(CardObjectTags.Standby);
    }

    private static bool IsWatchfulSentinelLastBreathDrawEffectForRecovery(string effectKind)
    {
        return string.Equals(effectKind, WatchfulSentinelLastBreathDrawEffectKindForRecovery, StringComparison.Ordinal);
    }

    private static string[] GetStandardLastBreathSourceCardNosForRecovery(string effectKind)
    {
        return effectKind switch
        {
            WatchfulSentinelLastBreathDrawEffectKindForRecovery => [WatchfulSentinelCardNoForRecovery],
            UnsungHeroLastBreathPowerfulDrawEffectKindForRecovery => [UnsungHeroCardNoForRecovery],
            ScoutingWarhawkLastBreathCallRuneEffectKindForRecovery => [ScoutingWarhawkCardNoForRecovery],
            SadPoroLastBreathDrawEffectKindForRecovery => [SadPoroOriginalCardNoForRecovery, SadPoroUnleashedCardNoForRecovery],
            LoyalPoroLastBreathDrawEffectKindForRecovery => [LoyalPoroCardNoForRecovery],
            HonestBrokerLastBreathCreateGoldEffectKindForRecovery => [HonestBrokerCardNoForRecovery],
            MechanicalTricksterLastBreathCreateMinionsEffectKindForRecovery => [MechanicalTricksterCardNoForRecovery],
            UndercoverAgentLastBreathEffectKindForRecovery => [UndercoverAgentCardNoForRecovery],
            IroncladVanguardLastBreathCreateRobotsEffectKindForRecovery => [IroncladVanguardCardNoForRecovery],
            MuddyDredgerLastBreathCreateWarhawkEffectKindForRecovery => [MuddyDredgerCardNoForRecovery],
            _ => []
        };
    }

    private static string[] GetFriendlyDestroyedSourceCardNosForRecovery(string effectKind)
    {
        return effectKind switch
        {
            GhostlyCentaurFriendlyDestroyedPowerEffectKindForRecovery => [GhostlyCentaurCardNoForRecovery],
            ResonantSoulFirstFriendlyDestroyedDrawEffectKindForRecovery => [ResonantSoulCardNoForRecovery],
            SavageJawfishFriendlyDestroyedExperienceEffectKindForRecovery => [SavageJawfishCardNoForRecovery],
            ViktorDestroyedNonMinionCreateMinionEffectKindForRecovery =>
            [
                ViktorDestroyedNonMinionArcCardNoForRecovery,
                ViktorDestroyedNonMinionOgnCardNoForRecovery,
                ViktorDestroyedNonMinionOgnAltACardNoForRecovery
            ],
            _ => []
        };
    }

    private static string FormatExpectedCardNosForRecovery(string[] cardNos)
    {
        return cardNos.Length == 1
            ? cardNos[0]
            : $"one of {string.Join(", ", cardNos)}";
    }

    private static void ValidateTriggerQueueControllerPlayerMembership(
        string payloadLabel,
        string? controllerId,
        IReadOnlySet<string>? knownPlayerIds,
        string knownPlayerLabel,
        List<string> errors)
    {
        if (controllerId is null
            || knownPlayerIds is null
            || string.Equals(controllerId, "HIDDEN", StringComparison.Ordinal))
        {
            return;
        }

        if (!knownPlayerIds.Contains(controllerId))
        {
            errors.Add($"{payloadLabel} controller id {controllerId} is missing from {knownPlayerLabel}");
        }
    }

    private static void ValidateTriggerQueueVisibleSourceObjectMembership(
        string payloadLabel,
        string? sourceObjectId,
        string? sourceVisibility,
        IReadOnlySet<string>? knownObjectIds,
        string knownObjectLabel,
        List<string> errors)
    {
        if (!string.Equals(sourceVisibility, "VISIBLE", StringComparison.Ordinal)
            || sourceObjectId is null
            || knownObjectIds is null
            || string.Equals(sourceObjectId, "HIDDEN", StringComparison.Ordinal))
        {
            return;
        }

        if (!knownObjectIds.Contains(sourceObjectId))
        {
            errors.Add($"{payloadLabel} visible source object id {sourceObjectId} is missing from {knownObjectLabel}");
        }
    }

    private static void ValidateTriggerQueuePromptFieldAbsence(
        object? triggerPayload,
        string payloadLabel,
        List<string> errors)
    {
        if (TryReadObjectValue(triggerPayload, "summary", out _))
        {
            errors.Add($"{payloadLabel} summary must be absent from timing trigger queue item");
        }

        if (TryReadObjectValue(triggerPayload, "visibleText", out _))
        {
            errors.Add($"{payloadLabel} visible text must be absent from timing trigger queue item");
        }
    }

    private static void ValidateTimingOrderTriggerPromptFieldAbsence(
        object? timingPayload,
        string timingLabel,
        List<string> errors)
    {
        ValidateTimingPromptFieldAbsence(timingPayload, "orderingPlayerId", timingLabel, errors);
        ValidateTimingPromptFieldAbsence(timingPayload, "orderedTriggerIds", timingLabel, errors);
        ValidateTimingPromptFieldAbsence(timingPayload, "triggerIds", timingLabel, errors);
        ValidateTimingPromptFieldAbsence(timingPayload, "triggers", timingLabel, errors);
        ValidateTimingPromptFieldAbsence(timingPayload, "triggerChoices", timingLabel, errors);
        ValidateTimingPromptFieldAbsence(timingPayload, "legalOrderingConstraints", timingLabel, errors);
        ValidateTimingPromptFieldAbsence(timingPayload, "triggeredByEventKind", timingLabel, errors);
        ValidateTimingPromptFieldAbsence(timingPayload, "orderingState", timingLabel, errors);
    }

    private static void ValidateTimingPromptFieldAbsence(
        object? timingPayload,
        string key,
        string timingLabel,
        List<string> errors)
    {
        if (!TryReadObjectValue(timingPayload, key, out _))
        {
            return;
        }

        errors.Add($"{timingLabel} order-trigger prompt field {key} must be absent");
    }

    private static bool OptionalStringSnapshotValueMatches(object? payload, string key, string? expected)
    {
        var expectedText = expected ?? string.Empty;
        if (!TryReadObjectValue(payload, key, out var value))
        {
            return string.IsNullOrEmpty(expectedText);
        }

        return TryReadOptionalStringValue(value, out var actual)
            && string.Equals(actual, expectedText, StringComparison.Ordinal);
    }

    private static bool OptionalIntSnapshotValueMatches(object? payload, string key, int? expected)
    {
        if (!TryReadObjectValue(payload, key, out var value))
        {
            return !expected.HasValue;
        }

        return expected.HasValue
            && TryReadIntValue(value, out var actual)
            && actual == expected.Value;
    }

    private static bool OptionalStringListSnapshotValueMatches(
        object? payload,
        string key,
        IReadOnlyList<string>? expected)
    {
        IReadOnlyList<string> expectedValues = expected ?? [];
        if (!TryReadObjectValue(payload, key, out var value))
        {
            return expectedValues.Count == 0;
        }

        return TryReadStringListValue(value, out var actual)
            && StringListsEqual(actual, expectedValues);
    }

    private static void ValidateSpectatorTemporaryPaymentResourcePayloads(
        IReadOnlyDictionary<string, object?> timing,
        MatchState authoritativeState,
        List<string> errors)
    {
        var authoritativeResources = authoritativeState.TemporaryPaymentResources;
        if (!timing.TryGetValue("temporaryPaymentResources", out var temporaryPaymentResourcesPayload)
            || IsNullSnapshotPayloadValue(temporaryPaymentResourcesPayload))
        {
            errors.Add("spectator replay frame timing temporary payment resources are required");
            if (authoritativeResources.Count > 0)
            {
                errors.Add(
                    $"spectator replay frame timing temporary payment resource count 0 does not match authoritative state temporary payment resource count {authoritativeResources.Count}");
            }

            return;
        }

        if (!TryReadObjectListValue(temporaryPaymentResourcesPayload, out var spectatorResources))
        {
            errors.Add("spectator replay frame timing temporary payment resources payload is required");
            return;
        }

        var validateAuthoritativeResourceParity = spectatorResources.Count == authoritativeResources.Count;
        if (!validateAuthoritativeResourceParity)
        {
            errors.Add(
                $"spectator replay frame timing temporary payment resource count {spectatorResources.Count} does not match authoritative state temporary payment resource count {authoritativeResources.Count}");
        }

        var seenResourceIds = new HashSet<string>(StringComparer.Ordinal);
        foreach (var spectatorResource in spectatorResources)
        {
            if (!IsSnapshotPlayerPayloadObject(spectatorResource))
            {
                errors.Add("spectator replay frame timing temporary payment resource payload is required");
                continue;
            }

            ValidateSnapshotPayloadObjectPropertyNames(
                spectatorResource,
                "spectator replay frame timing temporary payment resource item",
                errors);
            ValidateSpectatorTemporaryPaymentResourcePowerTraitPayloadPropertyNames(spectatorResource, errors);
            var resourceIdValue = ValidateSpectatorTemporaryPaymentResourcePayloadValues(spectatorResource, errors);
            if (resourceIdValue is not null && !seenResourceIds.Add(resourceIdValue))
            {
                errors.Add($"spectator replay frame timing temporary payment resource item resource id {resourceIdValue} is duplicated");
            }
        }

        var authoritativeResourcesById = new Dictionary<string, TemporaryPaymentResourceState>(StringComparer.Ordinal);
        foreach (var authoritativeResource in authoritativeResources)
        {
            if (string.IsNullOrWhiteSpace(authoritativeResource.ResourceId))
            {
                continue;
            }

            var normalizedResourceId = authoritativeResource.ResourceId.Trim();
            if (!authoritativeResourcesById.ContainsKey(normalizedResourceId))
            {
                authoritativeResourcesById.Add(normalizedResourceId, authoritativeResource);
            }
        }

        ValidateSpectatorTemporaryPaymentResourceAuthoritativeKeySet(
            spectatorResources,
            authoritativeResourcesById,
            errors);
        ValidateSpectatorTemporaryPaymentResourceKeyedAuthoritativeValues(
            spectatorResources,
            authoritativeResourcesById,
            errors);

        if (!validateAuthoritativeResourceParity)
        {
            return;
        }

        var resourceIdsMatch = true;
        var ownerPlayerIdsMatch = true;
        var sourceObjectIdsMatch = true;
        var abilityIdsMatch = true;
        var paymentWindowsMatch = true;
        var generatedPowersMatch = true;
        var remainingPowersMatch = true;
        var generatedPowerTraitsMatch = true;
        var remainingPowerTraitsMatch = true;
        var allowedPaymentKindsMatch = true;
        var paymentOnlyFlagsMatch = true;
        var resourceRestrictionsMatch = true;
        var createdTicksMatch = true;

        for (var index = 0; index < authoritativeResources.Count; index++)
        {
            var spectatorResource = spectatorResources[index];
            if (!IsSnapshotPlayerPayloadObject(spectatorResource))
            {
                continue;
            }

            var authoritativeResource = authoritativeResources[index];
            if (!TryReadObjectString(spectatorResource, "resourceId", out var resourceId)
                || !string.Equals(resourceId, authoritativeResource.ResourceId, StringComparison.Ordinal))
            {
                resourceIdsMatch = false;
            }

            if (!TryReadObjectString(spectatorResource, "ownerPlayerId", out var ownerPlayerId)
                || !string.Equals(ownerPlayerId, authoritativeResource.OwnerPlayerId, StringComparison.Ordinal))
            {
                ownerPlayerIdsMatch = false;
            }

            if (!TryReadObjectString(spectatorResource, "sourceObjectId", out var sourceObjectId)
                || !string.Equals(sourceObjectId, authoritativeResource.SourceObjectId, StringComparison.Ordinal))
            {
                sourceObjectIdsMatch = false;
            }

            if (!TryReadObjectString(spectatorResource, "abilityId", out var abilityId)
                || !string.Equals(abilityId, authoritativeResource.AbilityId, StringComparison.Ordinal))
            {
                abilityIdsMatch = false;
            }

            if (!TryReadObjectString(spectatorResource, "paymentWindow", out var paymentWindow)
                || !string.Equals(paymentWindow, authoritativeResource.PaymentWindow, StringComparison.Ordinal))
            {
                paymentWindowsMatch = false;
            }

            if (!TryReadObjectInt(spectatorResource, "generatedPower", out var generatedPower)
                || generatedPower != authoritativeResource.GeneratedPower)
            {
                generatedPowersMatch = false;
            }

            if (!TryReadObjectInt(spectatorResource, "remainingPower", out var remainingPower)
                || remainingPower != authoritativeResource.RemainingPower)
            {
                remainingPowersMatch = false;
            }

            if (!TryReadObjectIntDictionary(spectatorResource, "generatedPowerByTrait", out var generatedPowerByTrait)
                || !IntDictionariesEqual(generatedPowerByTrait, authoritativeResource.GeneratedPowerByTrait))
            {
                generatedPowerTraitsMatch = false;
            }

            if (!TryReadObjectIntDictionary(spectatorResource, "remainingPowerByTrait", out var remainingPowerByTrait)
                || !IntDictionariesEqual(remainingPowerByTrait, authoritativeResource.RemainingPowerByTrait))
            {
                remainingPowerTraitsMatch = false;
            }

            if (!TryReadObjectStringList(spectatorResource, "allowedPaymentKinds", out var allowedPaymentKinds)
                || !StringListsEqual(allowedPaymentKinds, authoritativeResource.AllowedPaymentKinds))
            {
                allowedPaymentKindsMatch = false;
            }

            if (!TryReadObjectBool(spectatorResource, "paymentOnly", out var paymentOnly)
                || !paymentOnly)
            {
                paymentOnlyFlagsMatch = false;
            }

            if (!TryReadObjectString(spectatorResource, "resourceRestriction", out var resourceRestriction)
                || !string.Equals(
                    resourceRestriction,
                    TemporaryPaymentResourceRestrictionForRecovery(authoritativeResource),
                    StringComparison.Ordinal))
            {
                resourceRestrictionsMatch = false;
            }

            if (!TryReadObjectLong(spectatorResource, "createdTick", out var createdTick)
                || createdTick != authoritativeResource.CreatedTick)
            {
                createdTicksMatch = false;
            }
        }

        if (!resourceIdsMatch)
        {
            errors.Add("spectator replay frame timing temporary payment resource ids disagree with authoritative state temporary payment resource ids");
        }

        if (!ownerPlayerIdsMatch)
        {
            errors.Add("spectator replay frame timing temporary payment resource owners disagree with authoritative state temporary payment resource owners");
        }

        if (!sourceObjectIdsMatch)
        {
            errors.Add("spectator replay frame timing temporary payment resource source objects disagree with authoritative state temporary payment resource source objects");
        }

        if (!abilityIdsMatch)
        {
            errors.Add("spectator replay frame timing temporary payment resource ability ids disagree with authoritative state temporary payment resource ability ids");
        }

        if (!paymentWindowsMatch)
        {
            errors.Add("spectator replay frame timing temporary payment resource payment windows disagree with authoritative state temporary payment resource payment windows");
        }

        if (!generatedPowersMatch)
        {
            errors.Add("spectator replay frame timing temporary payment resource generated powers disagree with authoritative state temporary payment resource generated powers");
        }

        if (!remainingPowersMatch)
        {
            errors.Add("spectator replay frame timing temporary payment resource remaining powers disagree with authoritative state temporary payment resource remaining powers");
        }

        if (!generatedPowerTraitsMatch)
        {
            errors.Add("spectator replay frame timing temporary payment resource generated power traits disagree with authoritative state temporary payment resource generated power traits");
        }

        if (!remainingPowerTraitsMatch)
        {
            errors.Add("spectator replay frame timing temporary payment resource remaining power traits disagree with authoritative state temporary payment resource remaining power traits");
        }

        if (!allowedPaymentKindsMatch)
        {
            errors.Add("spectator replay frame timing temporary payment resource allowed payment kinds disagree with authoritative state temporary payment resource allowed payment kinds");
        }

        if (!paymentOnlyFlagsMatch)
        {
            errors.Add("spectator replay frame timing temporary payment resource payment-only flags disagree with authoritative state temporary payment resource payment-only flags");
        }

        if (!resourceRestrictionsMatch)
        {
            errors.Add("spectator replay frame timing temporary payment resource restrictions disagree with authoritative state temporary payment resource restrictions");
        }

        if (!createdTicksMatch)
        {
            errors.Add("spectator replay frame timing temporary payment resource created ticks disagree with authoritative state temporary payment resource created ticks");
        }
    }

    private static void ValidateSpectatorTemporaryPaymentResourceAuthoritativeKeySet(
        IReadOnlyList<object?> resourcePayloads,
        IReadOnlyDictionary<string, TemporaryPaymentResourceState> authoritativeResourcesById,
        List<string> errors)
    {
        const string payloadLabel = "spectator replay frame timing temporary payment resource item";
        var actualResourceIds = new HashSet<string>(StringComparer.Ordinal);
        foreach (var resourcePayload in resourcePayloads)
        {
            if (!IsSnapshotPlayerPayloadObject(resourcePayload)
                || !TryReadObjectString(resourcePayload, "resourceId", out var resourceId)
                || string.IsNullOrWhiteSpace(resourceId))
            {
                continue;
            }

            var normalizedResourceId = resourceId.Trim();
            actualResourceIds.Add(normalizedResourceId);
            if (!authoritativeResourcesById.ContainsKey(normalizedResourceId))
            {
                errors.Add(
                    $"{payloadLabel} resource id {normalizedResourceId} is not present in authoritative state temporary payment resources");
            }
        }

        foreach (var authoritativeResourceId in authoritativeResourcesById.Keys.OrderBy(id => id, StringComparer.Ordinal))
        {
            if (!actualResourceIds.Contains(authoritativeResourceId))
            {
                errors.Add(
                    $"{payloadLabel} resource id {authoritativeResourceId} is required by authoritative state temporary payment resources");
            }
        }
    }

    private static void ValidateSpectatorTemporaryPaymentResourceKeyedAuthoritativeValues(
        IReadOnlyList<object?> resourcePayloads,
        IReadOnlyDictionary<string, TemporaryPaymentResourceState> authoritativeResourcesById,
        List<string> errors)
    {
        foreach (var resourcePayload in resourcePayloads)
        {
            if (!IsSnapshotPlayerPayloadObject(resourcePayload)
                || !TryReadObjectString(resourcePayload, "resourceId", out var resourceId)
                || string.IsNullOrWhiteSpace(resourceId))
            {
                continue;
            }

            var normalizedResourceId = resourceId.Trim();
            if (!authoritativeResourcesById.TryGetValue(normalizedResourceId, out var authoritativeResource))
            {
                continue;
            }

            ValidateSpectatorTemporaryPaymentResourceKeyedRequiredStringValue(
                resourcePayload,
                "ownerPlayerId",
                "owner player id",
                authoritativeResource.OwnerPlayerId,
                normalizedResourceId,
                errors);
            ValidateSpectatorTemporaryPaymentResourceKeyedOptionalStringValue(
                resourcePayload,
                "sourceObjectId",
                "source object id",
                authoritativeResource.SourceObjectId,
                normalizedResourceId,
                errors);
            ValidateSpectatorTemporaryPaymentResourceKeyedOptionalStringValue(
                resourcePayload,
                "abilityId",
                "ability id",
                authoritativeResource.AbilityId,
                normalizedResourceId,
                errors);
            ValidateSpectatorTemporaryPaymentResourceKeyedOptionalStringValue(
                resourcePayload,
                "paymentWindow",
                "payment window",
                authoritativeResource.PaymentWindow,
                normalizedResourceId,
                errors);
            ValidateSpectatorTemporaryPaymentResourceKeyedRequiredIntValue(
                resourcePayload,
                "generatedPower",
                "generated power",
                authoritativeResource.GeneratedPower,
                normalizedResourceId,
                errors);
            ValidateSpectatorTemporaryPaymentResourceKeyedRequiredIntValue(
                resourcePayload,
                "remainingPower",
                "remaining power",
                authoritativeResource.RemainingPower,
                normalizedResourceId,
                errors);
            ValidateSpectatorTemporaryPaymentResourceKeyedRequiredIntDictionaryValue(
                resourcePayload,
                "generatedPowerByTrait",
                "generated power traits",
                authoritativeResource.GeneratedPowerByTrait,
                normalizedResourceId,
                errors);
            ValidateSpectatorTemporaryPaymentResourceKeyedRequiredIntDictionaryValue(
                resourcePayload,
                "remainingPowerByTrait",
                "remaining power traits",
                authoritativeResource.RemainingPowerByTrait,
                normalizedResourceId,
                errors);
            ValidateSpectatorTemporaryPaymentResourceKeyedRequiredStringListValue(
                resourcePayload,
                "allowedPaymentKinds",
                "allowed payment kinds",
                authoritativeResource.AllowedPaymentKinds,
                normalizedResourceId,
                errors);
            ValidateSpectatorTemporaryPaymentResourceKeyedRequiredTrueBoolValue(
                resourcePayload,
                "paymentOnly",
                "payment-only flag",
                normalizedResourceId,
                errors);
            ValidateSpectatorTemporaryPaymentResourceKeyedRequiredStringValue(
                resourcePayload,
                "resourceRestriction",
                "resource restriction",
                TemporaryPaymentResourceRestrictionForRecovery(authoritativeResource),
                normalizedResourceId,
                errors);
            ValidateSpectatorTemporaryPaymentResourceKeyedRequiredLongValue(
                resourcePayload,
                "createdTick",
                "created tick",
                authoritativeResource.CreatedTick,
                normalizedResourceId,
                errors);
        }
    }

