    public static IReadOnlyDictionary<string, string> ExtractSeats(SnapshotDto snapshot)
    {
        var seats = new Dictionary<string, string>(StringComparer.Ordinal);
        if (snapshot.Players is null)
        {
            return seats;
        }

        foreach (var (playerId, player) in snapshot.Players)
        {
            if (TryReadSeat(player, out var seat))
            {
                seats[playerId] = seat;
            }
        }

        return seats;
    }

    private static void ValidateSpectatorSnapshotStackItemPayloads(
        SnapshotDto snapshot,
        MatchState authoritativeState,
        List<string> errors)
    {
        if (snapshot.Stack is null)
        {
            return;
        }

        var seenStackItemIds = new HashSet<string>(StringComparer.Ordinal);
        for (var index = 0; index < snapshot.Stack.Count; index++)
        {
            var stackItem = snapshot.Stack[index];
            var stackItemLabel = index < authoritativeState.StackItems.Count
                ? authoritativeState.StackItems[index].StackItemId
                : TryReadObjectString(stackItem, "stackItemId", out var stackItemId)
                    && !string.IsNullOrWhiteSpace(stackItemId)
                    ? stackItemId
                    : $"#{index + 1}";
            if (!IsSnapshotPlayerPayloadObject(stackItem))
            {
                errors.Add($"spectator replay frame snapshot stack item {stackItemLabel} payload is required");
                continue;
            }

            ValidateSnapshotPayloadObjectPropertyNames(
                stackItem,
                $"spectator replay frame snapshot stack item {stackItemLabel}",
                errors);
            var normalizedStackItemId = ValidateSpectatorSnapshotStackItemPayloadValues(stackItem, stackItemLabel, errors);
            if (normalizedStackItemId is not null && !seenStackItemIds.Add(normalizedStackItemId))
            {
                errors.Add($"spectator replay frame snapshot stack item {normalizedStackItemId} is duplicated");
            }
        }
    }

    private static void ValidateSpectatorSnapshotStackPlayerReferences(
        IReadOnlyList<object?> stackItems,
        IReadOnlySet<string> knownPlayerIds,
        List<string> errors)
    {
        for (var index = 0; index < stackItems.Count; index++)
        {
            var stackItem = stackItems[index];
            if (!IsSnapshotPlayerPayloadObject(stackItem))
            {
                continue;
            }

            var stackItemLabel = TryReadObjectString(stackItem, "stackItemId", out var stackItemId)
                && !string.IsNullOrWhiteSpace(stackItemId)
                ? stackItemId.Trim()
                : $"#{index + 1}";
            if (!TryReadObjectString(stackItem, "controllerId", out var controllerId)
                || string.IsNullOrWhiteSpace(controllerId))
            {
                continue;
            }

            ValidateTimingPlayerReference(
                $"spectator replay frame snapshot stack item {stackItemLabel} controller player",
                controllerId,
                knownPlayerIds,
                "seats",
                errors);
        }
    }

    private static void ValidateSpectatorSnapshotStackObjectReferences(
        IReadOnlyList<object?> stackItems,
        IReadOnlySet<string> knownObjectIds,
        List<string> errors)
    {
        for (var index = 0; index < stackItems.Count; index++)
        {
            var stackItem = stackItems[index];
            if (!IsSnapshotPlayerPayloadObject(stackItem))
            {
                continue;
            }

            var stackItemLabel = TryReadObjectString(stackItem, "stackItemId", out var stackItemId)
                && !string.IsNullOrWhiteSpace(stackItemId)
                ? stackItemId.Trim()
                : $"#{index + 1}";
            ValidateTimingOptionalObjectReference(
                stackItem,
                "sourceObjectId",
                $"spectator replay frame snapshot stack item {stackItemLabel} source object id",
                knownObjectIds,
                "object registry",
                errors);
            ValidateTimingObjectReferenceList(
                stackItem,
                "targetObjectIds",
                $"spectator replay frame snapshot stack item {stackItemLabel} target object id",
                knownObjectIds,
                "object registry",
                errors);
        }
    }

    private static void ValidateSpectatorSnapshotStackKeyedAuthoritativeValues(
        IReadOnlyList<object?> stackItems,
        IReadOnlyList<StackItemState> authoritativeStackItems,
        List<string> errors)
    {
        var authoritativeStackItemsById = new Dictionary<string, StackItemState>(StringComparer.Ordinal);
        foreach (var authoritativeStackItem in authoritativeStackItems)
        {
            if (string.IsNullOrWhiteSpace(authoritativeStackItem.StackItemId))
            {
                continue;
            }

            var normalizedStackItemId = authoritativeStackItem.StackItemId.Trim();
            if (!authoritativeStackItemsById.ContainsKey(normalizedStackItemId))
            {
                authoritativeStackItemsById.Add(normalizedStackItemId, authoritativeStackItem);
            }
        }

        foreach (var stackItem in stackItems)
        {
            if (!IsSnapshotPlayerPayloadObject(stackItem)
                || !TryReadObjectString(stackItem, "stackItemId", out var stackItemId)
                || string.IsNullOrWhiteSpace(stackItemId))
            {
                continue;
            }

            var normalizedStackItemId = stackItemId.Trim();
            if (!authoritativeStackItemsById.TryGetValue(normalizedStackItemId, out var authoritativeStackItem))
            {
                continue;
            }

            ValidateSpectatorSnapshotStackKeyedRequiredStringValue(
                stackItem,
                "controllerId",
                "controller id",
                authoritativeStackItem.ControllerId,
                normalizedStackItemId,
                errors);
            ValidateSpectatorSnapshotStackKeyedOptionalStringValue(
                stackItem,
                "sourceObjectId",
                "source object id",
                authoritativeStackItem.SourceObjectId,
                normalizedStackItemId,
                errors);
            ValidateSpectatorSnapshotStackKeyedRequiredStringValue(
                stackItem,
                "effectKind",
                "effect kind",
                authoritativeStackItem.EffectKind,
                normalizedStackItemId,
                errors);
            ValidateSpectatorSnapshotStackKeyedOptionalStringValue(
                stackItem,
                "cardNo",
                "card no",
                authoritativeStackItem.CardNo,
                normalizedStackItemId,
                errors);
            ValidateSpectatorSnapshotStackKeyedRequiredStringListValue(
                stackItem,
                "targetObjectIds",
                "target object ids",
                authoritativeStackItem.TargetObjectIds,
                normalizedStackItemId,
                errors);
            ValidateSpectatorSnapshotStackKeyedRequiredIntValue(
                stackItem,
                "damageAmount",
                "damage amount",
                authoritativeStackItem.DamageAmount,
                normalizedStackItemId,
                errors);
            ValidateSpectatorSnapshotStackKeyedOptionalStringValue(
                stackItem,
                "destination",
                "destination",
                authoritativeStackItem.Destination,
                normalizedStackItemId,
                errors);
        }
    }

    private static void ValidateSpectatorSnapshotStackKeyedRequiredStringValue(
        object? stackItem,
        string key,
        string fieldLabel,
        string expected,
        string stackItemId,
        List<string> errors)
    {
        const string payloadLabel = "spectator replay frame snapshot stack item";
        if (!TryReadObjectString(stackItem, key, out var actual))
        {
            errors.Add(
                $"{payloadLabel} {fieldLabel} does not match authoritative state stack item {fieldLabel} {expected} for stack item id {stackItemId}");
            return;
        }

        if (!string.Equals(actual, expected, StringComparison.Ordinal))
        {
            errors.Add(
                $"{payloadLabel} {fieldLabel} {actual} does not match authoritative state stack item {fieldLabel} {expected} for stack item id {stackItemId}");
        }
    }

    private static void ValidateSpectatorSnapshotStackKeyedOptionalStringValue(
        object? stackItem,
        string key,
        string fieldLabel,
        string? expected,
        string stackItemId,
        List<string> errors)
    {
        const string payloadLabel = "spectator replay frame snapshot stack item";
        var expectedText = expected ?? string.Empty;
        if (!TryReadObjectOptionalString(stackItem, key, out var actual))
        {
            if (!string.IsNullOrEmpty(expectedText))
            {
                errors.Add(
                    $"{payloadLabel} {fieldLabel} does not match authoritative state stack item {fieldLabel} {expectedText} for stack item id {stackItemId}");
            }

            return;
        }

        if (!string.Equals(actual, expectedText, StringComparison.Ordinal))
        {
            errors.Add(
                $"{payloadLabel} {fieldLabel} {actual} does not match authoritative state stack item {fieldLabel} {expectedText} for stack item id {stackItemId}");
        }
    }

    private static void ValidateSpectatorSnapshotStackKeyedRequiredStringListValue(
        object? stackItem,
        string key,
        string fieldLabel,
        IReadOnlyList<string> expected,
        string stackItemId,
        List<string> errors)
    {
        const string payloadLabel = "spectator replay frame snapshot stack item";
        if (!TryReadObjectStringList(stackItem, key, out var actual)
            || !StringListsEqual(actual, expected))
        {
            errors.Add(
                $"{payloadLabel} {fieldLabel} do not match authoritative state stack item {fieldLabel} for stack item id {stackItemId}");
        }
    }

    private static void ValidateSpectatorSnapshotStackKeyedRequiredIntValue(
        object? stackItem,
        string key,
        string fieldLabel,
        int expected,
        string stackItemId,
        List<string> errors)
    {
        const string payloadLabel = "spectator replay frame snapshot stack item";
        if (!TryReadObjectInt(stackItem, key, out var actual))
        {
            errors.Add(
                $"{payloadLabel} {fieldLabel} does not match authoritative state stack item {fieldLabel} {expected} for stack item id {stackItemId}");
            return;
        }

        if (actual != expected)
        {
            errors.Add(
                $"{payloadLabel} {fieldLabel} {actual} does not match authoritative state stack item {fieldLabel} {expected} for stack item id {stackItemId}");
        }
    }

    private static void ValidateSpectatorSnapshotStackAuthoritativeKeySet(
        IReadOnlyList<object?> stackItems,
        IReadOnlyList<StackItemState> authoritativeStackItems,
        List<string> errors)
    {
        var authoritativeStackItemIds = authoritativeStackItems
            .Select(item => item.StackItemId)
            .Where(id => !string.IsNullOrWhiteSpace(id))
            .Select(id => id.Trim())
            .ToHashSet(StringComparer.Ordinal);
        var actualStackItemIds = new HashSet<string>(StringComparer.Ordinal);
        foreach (var stackItem in stackItems)
        {
            if (!IsSnapshotPlayerPayloadObject(stackItem)
                || !TryReadObjectString(stackItem, "stackItemId", out var stackItemId)
                || string.IsNullOrWhiteSpace(stackItemId))
            {
                continue;
            }

            var normalizedStackItemId = stackItemId.Trim();
            actualStackItemIds.Add(normalizedStackItemId);
            if (!authoritativeStackItemIds.Contains(normalizedStackItemId))
            {
                errors.Add(
                    $"spectator replay frame snapshot stack item id {normalizedStackItemId} is not present in authoritative state stack items");
            }
        }

        foreach (var authoritativeStackItemId in authoritativeStackItemIds.OrderBy(id => id, StringComparer.Ordinal))
        {
            if (!actualStackItemIds.Contains(authoritativeStackItemId))
            {
                errors.Add(
                    $"spectator replay frame snapshot stack item id {authoritativeStackItemId} is required by authoritative state stack items");
            }
        }
    }

    private static string? ValidateSpectatorSnapshotStackItemPayloadValues(
        object? stackItem,
        string stackItemLabel,
